  if (vt == (void*)&SharedObject_vt) return SharedObject_amf_members;
  if (vt == (void*)&StatusEvent_vt) return StatusEvent_amf_members;
  if (vt == (void*)&ExtensionContext_vt) return ExtensionContext_amf_members;
  if (vt == (void*)&JPEGEncoderOptions_vt) return JPEGEncoderOptions_amf_members;
  if (vt == (void*)&PNGEncoderOptions_vt) return PNGEncoderOptions_amf_members;
