#ifdef ASC_HAVE_FRE
static void* as_fre_ba_data_impl(void* ba, unsigned* len) {
  ByteArray* b = (ByteArray*)ba;
  if (len != NULL) *len = b->length > 0 ? (unsigned)b->length : 0u;
  return b->length > 0 ? b->data : NULL;
}
static void* as_fre_ba_new_impl(unsigned len) {
  ByteArray* b = ByteArray_new();
  if (len > 0) ByteArray_set_length(b, len);
  return b;
}
static void as_fre_status_impl(void* as3ctx, const char* code, const char* level) {
  jmp_buf jb;
  if (setjmp(jb) != 0) {
    as_jmp_pop();
    as_value m = as_exception_boxed ? as_exception_v : as_v_obj(as_exception);
    as_exception = NULL; as_exception_boxed = 0;
    fprintf(stderr, "Uncaught exception in StatusEvent handler: %s\n", as_v_str_val(m));
    fflush(stderr);
    return;
  }
  as_jmp_push(&jb);
  StatusEvent* ev = StatusEvent_new((char*)"status", false, false, as_str_dup(code), as_str_dup(level));
  as_value a = as_v_obj((void*)ev);
  as_dyn_call(as3ctx, "dispatchEvent", &a, 1);
  as_jmp_pop();
}
static void as_fre_wire_classes(void) {
  as_fre_ba_data_hook = as_fre_ba_data_impl;
  as_fre_ba_new_hook = as_fre_ba_new_impl;
  as_fre_status_hook = as_fre_status_impl;
}
#endif // ASC_HAVE_FRE

