static void StyleSheet_setStyle(void* _this, char* styleName, Object* styleObject) {
  StyleSheet* ss = (StyleSheet*)_this;
  if (ss == NULL || styleName == NULL) return;
  char* key = as_str_toLower(styleName);
  if (styleObject == NULL) { as_object_del(ss->_rules, key); return; }
  as_object_set(ss->_rules, key, as_v_obj((void*)as_object_clone((as_object*)styleObject)));
}
static Object* StyleSheet_getStyle(void* _this, char* styleName) {
  StyleSheet* ss = (StyleSheet*)_this;
  if (ss == NULL || styleName == NULL) return NULL;
  as_object* decl = as_ss_lookup(ss->_rules, styleName);
  if (decl == NULL) return NULL;
  return (Object*)(void*)as_object_clone(decl);
}
static void StyleSheet_clear(void* _this) { StyleSheet* ss = (StyleSheet*)_this; if (ss != NULL) ss->_rules = as_object_new(); }
static as_array* StyleSheet_get_styleNames(void* _this) {
  StyleSheet* ss = (StyleSheet*)_this;
  as_array* a = as_array_new();
  if (ss == NULL) return a;
  for (int i = 0; i < ss->_rules->length; i++) as_array_push(a, as_v_str(ss->_rules->keys[i]));
  return a;
}
