static char* SQLError_toString(void* _this) {
  SQLError* e = (SQLError*)_this;
  const char* parts[11]; int n = 0;
  parts[n++] = "SQLError: '"; parts[n++] = (e->message != NULL) ? e->message : ""; parts[n++] = "', details:'";
  parts[n++] = (e->_details != NULL) ? e->_details : ""; parts[n++] = "', operation:'";
  parts[n++] = (e->_operation != NULL) ? e->_operation : ""; parts[n++] = "'";
  if (e->_detailID >= 0) { parts[n++] = ", detailID:'"; parts[n++] = as_str_from_int(e->_detailID); parts[n++] = "'"; }
  return as_str_concat_n(n, parts);
}

static as_xml_node* as_xml_parse_checked(const char* src, int len) {
  as_xml_node* n = as_xml_parse(src, len);
  if (n == NULL) as_throw(TypeError_new(as_xml_error_message(), as_xml_error_id()));
  return n;
}
static as_xml_node* as_xml_parse_str_checked(const char* src) {
  return as_xml_parse_checked(src, src == NULL ? 0 : (int)strlen(src));
}
static as_xml_node* as_xml_parse_bytes_checked(ByteArray* bytes) {
  if (bytes == NULL) return as_xml_parse_checked("", 0);
  return as_xml_parse_checked(bytes->data == NULL ? "" : (const char*)bytes->data, (int)bytes->length);
}
static as_xml_node* as_xml_from_value(as_value v) {
  if (v.tag == 3) return as_xml_parse_str_checked((char*)v.ptr);
  if (v.tag == 4 && as_is(as_v_obj_val(v), &as_xml_vt)) return (as_xml_node*)as_v_obj_val(v);
  if (v.tag == 4 && as_is(as_v_obj_val(v), &as_xml_list_vt)) { as_xml_list* l = (as_xml_list*)as_v_obj_val(v); return l != NULL && l->length > 0 ? l->items[0] : NULL; }
  if (v.tag == 4 && as_is(as_v_obj_val(v), &ByteArray_vt)) return as_xml_parse_bytes_checked((ByteArray*)as_v_obj_val(v));
  as_throw_unsupported("XML(value) is only supported for String, XML and ByteArray values by this subset");
  return NULL;
}

static void Date_ctor(Date* o) { o->_time = as_now_ms(); }
static Date* Date_new(void) {
  Date* o = (Date*)gc_alloc(GCT_CLASS, sizeof(Date));
  o->vtable = &Date_vt;
  Date_ctor(o);
  return o;
}
static Date* Date_new_ms(double ms) {
  Date* o = (Date*)gc_alloc(GCT_CLASS, sizeof(Date));
  o->vtable = &Date_vt;
  o->_time = ms;
  return o;
}
static double Date_mkms(int year, int mon, int day, int hour, int min, int sec, int ms) {
  struct tm t;
  memset(&t, 0, sizeof(t));
  t.tm_year = (year >= 100) ? (year - 1900) : year;
  t.tm_mon = mon;
  t.tm_mday = day;
  t.tm_hour = hour;
  t.tm_min = min;
  t.tm_sec = sec;
  t.tm_isdst = -1;
  time_t tt = mktime(&t);
  return (double)tt * 1000.0 + (double)ms;
}
static Date* Date_new_ymd(int year, int mon, int day, int hour, int min, int sec, int ms) {
  Date* o = (Date*)gc_alloc(GCT_CLASS, sizeof(Date));
  o->vtable = &Date_vt;
  o->_time = Date_mkms(year, mon, day, hour, min, sec, ms);
  return o;
}
static as_array* Font_enumerateFonts_static(bool enumerateDeviceFonts) { (void)enumerateDeviceFonts; return as_array_new(); }
static double Date_parse_static(char* s) {
  int year = 0, mon = 0, day = 1, hour = 0, min = 0, sec = 0;
  int n = sscanf(s, "%d/%d/%d %d:%d:%d", &year, &mon, &day, &hour, &min, &sec);
  if (n < 3) n = sscanf(s, "%d/%d/%d", &year, &mon, &day);
  if (n < 3) n = sscanf(s, "%d-%d-%dT%d:%d:%d", &year, &mon, &day, &hour, &min, &sec);
  if (n < 3) n = sscanf(s, "%d-%d-%d", &year, &mon, &day);
  if (n < 3) return NAN;
  return Date_mkms(year, mon - 1, day, hour, min, sec, 0);
}
static struct tm* Date_tm(Date* o) { time_t t = (time_t)(o->_time / 1000.0); return localtime(&t); }
static double Date_getTime(void* _this) { return ((Date*)_this)->_time; }
static int as_amf_date_is(as_value v, double* ms) {
  if (v.tag != 4 || v.ptr == NULL) return 0;
  if (((as_object_header*)v.ptr)->vtable != (void*)&Date_vt) return 0;
  *ms = ((Date*)v.ptr)->_time;
  return 1;
}
static as_value as_amf_date_new(double ms) { Date* d = Date_new(); d->_time = ms; return as_v_obj(d); }
static int Date_getFullYear(void* _this) { return Date_tm((Date*)_this)->tm_year + 1900; }
static int Date_getMonth(void* _this) { return Date_tm((Date*)_this)->tm_mon; }
static int Date_getDate(void* _this) { return Date_tm((Date*)_this)->tm_mday; }
static int Date_getDay(void* _this) { return Date_tm((Date*)_this)->tm_wday; }
static int Date_getHours(void* _this) { return Date_tm((Date*)_this)->tm_hour; }
static int Date_getMinutes(void* _this) { return Date_tm((Date*)_this)->tm_min; }
static int Date_getSeconds(void* _this) { return Date_tm((Date*)_this)->tm_sec; }
static int Date_get_milliseconds(void* _this) { double raw = fmod(((Date*)_this)->_time, 1000.0); int ms = (int)raw; if (ms < 0) ms += 1000; return ms; }
static void Date_set_milliseconds(void* _this, double value) {
  Date* o = (Date*)_this;
  double base = floor(o->_time / 1000.0) * 1000.0;
  o->_time = base + value;
}
static int Date_get_millisecondsUTC(void* _this) { return Date_get_milliseconds(_this); }
static void Date_set_millisecondsUTC(void* _this, double value) { Date_set_milliseconds(_this, value); }
static int Date_get_fullYear(void* _this) { return Date_getFullYear(_this); }
static int Date_get_month(void* _this) { return Date_getMonth(_this); }
static int Date_get_date(void* _this) { return Date_getDate(_this); }
static int Date_get_day(void* _this) { return Date_getDay(_this); }
static int Date_get_hours(void* _this) { return Date_getHours(_this); }
static int Date_get_minutes(void* _this) { return Date_getMinutes(_this); }
static int Date_get_seconds(void* _this) { return Date_getSeconds(_this); }
static void as_date_set_component(Date* o, int which, double value) {
  if (!(value == value)) { o->_time = NAN; return; }  /* NaN component: the date is invalid */
  struct tm t = *Date_tm(o);
  switch (which) {
    case 0: t.tm_year = (int)value - 1900; break;
    case 1: t.tm_mon = (int)value; break;
    case 2: t.tm_mday = (int)value; break;
    case 3: t.tm_hour = (int)value; break;
    case 4: t.tm_min = (int)value; break;
    case 5: t.tm_sec = (int)value; break;
    default: break;
  }
  t.tm_isdst = -1;  /* let mktime pick the DST offset for the new wall-clock time */
  time_t secs = mktime(&t);
  if (secs == (time_t)-1) { o->_time = NAN; return; }
  double sub = fmod(o->_time, 1000.0); if (sub < 0) sub += 1000.0;
  o->_time = (double)secs * 1000.0 + sub;
}
static void Date_set_fullYear(void* _this, double value) { as_date_set_component((Date*)_this, 0, value); }
static void Date_set_month(void* _this, double value) { as_date_set_component((Date*)_this, 1, value); }
static void Date_set_date(void* _this, double value) { as_date_set_component((Date*)_this, 2, value); }
static void Date_set_hours(void* _this, double value) { as_date_set_component((Date*)_this, 3, value); }
static void Date_set_minutes(void* _this, double value) { as_date_set_component((Date*)_this, 4, value); }
static void Date_set_seconds(void* _this, double value) { as_date_set_component((Date*)_this, 5, value); }
static char* Date_toDateString(void* _this) {
  struct tm* t = Date_tm((Date*)_this);
  static const char* days[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};
  static const char* months[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
  char* r = as_str_alloc(32);
  snprintf(r, 32, "%s %s %02d %04d", days[t->tm_wday], months[t->tm_mon], t->tm_mday, t->tm_year + 1900);
  return r;
}
static char* Date_toTimeString(void* _this) {
  struct tm* t = Date_tm((Date*)_this);
  time_t tt = (time_t)(((Date*)_this)->_time / 1000.0);
  struct tm lt = *t, gt = *gmtime(&tt);
  gt.tm_isdst = -1;
  long off = (long)(mktime(&lt) - mktime(&gt));
  char* r = as_str_alloc(48);
  int hh = (int)(off / 3600), mm = (int)((off < 0 ? -off : off) % 3600) / 60;
  snprintf(r, 48, "%02d:%02d:%02d GMT%c%02d%02d", t->tm_hour, t->tm_min, t->tm_sec, off < 0 ? '-' : '+', hh < 0 ? -hh : hh, mm);
  return r;
}
static char* Date_toLocaleTimeString(void* _this) {
  char* full = Date_toTimeString(_this);
  char* sp = strstr(full, " GMT");
  if (sp == NULL) return full;
  int n = (int)(sp - full);
  char* r = as_str_alloc(n + 1);
  memcpy(r, full, (size_t)n); r[n] = 0;
  return r;
}
static char* Date_toUTCString(void* _this) {
  time_t t = (time_t)(((Date*)_this)->_time / 1000.0);
  struct tm* g = gmtime(&t);
  static const char* days[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};
  static const char* months[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
  char* r = as_str_alloc(40);
  snprintf(r, 40, "%s, %02d %s %04d %02d:%02d:%02d GMT", days[g->tm_wday], g->tm_mday, months[g->tm_mon], g->tm_year + 1900, g->tm_hour, g->tm_min, g->tm_sec);
  return r;
}

static void RegExp_ctor(RegExp* o, char* pattern, char* flags) {
  o->source = pattern;
  o->flags = flags;
  gc_write_barrier((void*)pattern);
  gc_write_barrier((void*)flags);
  o->lastIndex = 0;
  o->global = (flags != NULL && strchr(flags, 'g') != NULL);
  o->ignoreCase = (flags != NULL && strchr(flags, 'i') != NULL);
  o->multiline = (flags != NULL && strchr(flags, 'm') != NULL);
  o->dotall = (flags != NULL && strchr(flags, 's') != NULL);
  o->extended = (flags != NULL && strchr(flags, 'x') != NULL);
  o->compiled = as_regex_compile(pattern, flags);
  // Inert when the pattern failed to compile: as_regex_search returns -1 on err.
}
static RegExp* RegExp_new(char* pattern, char* flags) {
  RegExp* o = (RegExp*)gc_alloc(GCT_CLASS, sizeof(RegExp));
  o->vtable = &RegExp_vt;
  RegExp_ctor(o, pattern, flags);
  return o;
}
static as_array* RegExp_exec(void* _this, char* s) {
  RegExp* re = (RegExp*)_this;
  if (re->compiled == NULL || re->compiled->err) return NULL;
  int len = (int)strlen(s);
  int cap[2 * (AS_RE_MAX_GROUPS + 1)];
  for (int i = 0; i < 2 * (re->compiled->ngroups + 1); i++) cap[i] = -1;
  int start = re->global ? re->lastIndex : 0;
  int end = -1;
  int m = as_regex_search(re->compiled, s, len, start, cap, &end);
  if (m < 0) { if (re->global) re->lastIndex = 0; return NULL; }
  if (re->global) re->lastIndex = end;
  return as_regex_make_result(s, m, end, re->compiled, cap);
}
static bool RegExp_test(void* _this, char* s) {
  RegExp* re = (RegExp*)_this;
  if (re->compiled == NULL || re->compiled->err) return false;
  int len = (int)strlen(s);
  int cap[2 * (AS_RE_MAX_GROUPS + 1)];
  for (int i = 0; i < 2 * (re->compiled->ngroups + 1); i++) cap[i] = -1;
  int start = re->global ? re->lastIndex : 0;
  int end = -1;
  int m = as_regex_search(re->compiled, s, len, start, cap, &end);
  if (m < 0) { if (re->global) re->lastIndex = 0; return false; }
  if (re->global) re->lastIndex = end;
  return true;
}

static as_value as_str_dyn_call(char* s, const char* name, as_value* args, int argc) {
  if (strcmp(name, "match") == 0) {
    as_regex* re = args[0].tag == 4 ? ((RegExp*)args[0].ptr)->compiled : as_regex_compile(as_v_str_val(args[0]), "");
    int global = args[0].tag == 4 ? ((RegExp*)args[0].ptr)->global : 0;
    return as_v_arr((void*)as_str_match_regex(s, re, global));
  }
  if (strcmp(name, "search") == 0) {
    as_regex* re = args[0].tag == 4 ? ((RegExp*)args[0].ptr)->compiled : as_regex_compile(as_v_str_val(args[0]), "");
    return as_v_num((double)as_str_search_regex(s, re));
  }
  if (strcmp(name, "replace") == 0) {
    if (args[0].tag == 4) {
      RegExp* re = (RegExp*)args[0].ptr;
      return as_v_str(as_str_replace_regex(s, re->compiled, argc >= 2 ? as_v_str_val(args[1]) : "", re->global));
    }
    return as_v_str(as_str_replace(s, as_v_str_val(args[0]), argc >= 2 ? as_v_str_val(args[1]) : ""));
  }
  if (strcmp(name, "charAt") == 0) return as_v_str(as_str_charAt(s, as_v_int_cast(args[0])));
  if (strcmp(name, "charCodeAt") == 0) return as_v_num((double)as_str_charCodeAt(s, as_v_int_cast(args[0])));
  if (strcmp(name, "indexOf") == 0) return as_v_num((double)as_str_indexOf_from(s, as_v_str_val(args[0]), argc >= 2 ? as_v_int_cast(args[1]) : 0));
  if (strcmp(name, "lastIndexOf") == 0) return as_v_num((double)as_str_lastIndexOf_from(s, as_v_str_val(args[0]), argc >= 2 ? as_v_int_cast(args[1]) : 0x7FFFFFFF));
  if (strcmp(name, "substring") == 0) {
    int from = as_v_int_cast(args[0]);
    int to = argc >= 2 ? as_v_int_cast(args[1]) : (int)strlen(s);
    return as_v_str(as_str_substring(s, from, to));
  }
  if (strcmp(name, "substr") == 0) {
    int from = as_v_int_cast(args[0]);
    int len = argc >= 2 ? as_v_int_cast(args[1]) : (int)strlen(s);
    return as_v_str(as_str_substr(s, from, len));
  }
  if (strcmp(name, "slice") == 0) {
    int from = as_v_int_cast(args[0]);
    int to = argc >= 2 ? as_v_int_cast(args[1]) : (int)strlen(s);
    return as_v_str(as_str_slice(s, from, to));
  }
  if (strcmp(name, "split") == 0) return as_v_arr((void*)as_str_split(s, as_v_str_val(args[0])));
  if (strcmp(name, "toUpperCase") == 0) return as_v_str(as_str_toUpper(s));
  if (strcmp(name, "toLowerCase") == 0) return as_v_str(as_str_toLower(s));
  if (strcmp(name, "toLocaleLowerCase") == 0) return as_v_str(as_str_toLower(s));
  if (strcmp(name, "toLocaleUpperCase") == 0) return as_v_str(as_str_toUpper(s));
  if (strcmp(name, "concat") == 0) {
    char* r = s;
    for (int i = 0; i < argc; i++) r = as_str_concat(r, as_v_str_val(args[i]));
    return as_v_str(r);
  }
  if (strcmp(name, "localeCompare") == 0) {
    const char* o = argc >= 1 ? as_v_str_val(args[0]) : "undefined";
    return as_v_num((double)as_str_localeCompare(s, o == NULL ? "null" : o));
  }
  if (strcmp(name, "startsWith") == 0) {
    const char* o = argc >= 1 ? as_v_str_val(args[0]) : "undefined";
    return as_v_bool(as_str_startsWith(s, o == NULL ? "null" : o));
  }
  if (strcmp(name, "endsWith") == 0) {
    const char* o = argc >= 1 ? as_v_str_val(args[0]) : "undefined";
    return as_v_bool(as_str_endsWith(s, o == NULL ? "null" : o));
  }
  if (strcmp(name, "toString") == 0 || strcmp(name, "valueOf") == 0) return as_v_str(s);
  return as_v_null();
}

static as_value as_any_call(as_value v, const char* name, as_value* args, int argc) {
  v = as_req_box(v);
  if (v.tag == 3) return as_str_dyn_call((char*)v.ptr, name, args, argc);
  if (v.tag == 6) return as_arr_call((as_array*)v.ptr, name, args, argc);
  return as_dyn_call(v.ptr, name, args, argc);
}

static char* as_disp_key(const char* type, bool capture) {
  size_t n = strlen(type) + 5;
  char* k = as_str_alloc(n);
  snprintf(k, n, "%s#%s", type, capture ? "cap" : "bub");
  return k;
}
static as_value as_listeners_get(as_object* listeners, const char* type, bool capture) {
  if (listeners == NULL) return as_v_null();
  char k[64];
  snprintf(k, sizeof(k), "%s#%s", type, capture ? "cap" : "bub");
  return as_object_get(listeners, k);
}
static void** as_ef_objs = NULL;
static int as_ef_count = 0;
static int as_ef_cap = 0;
static void as_ef_register(void* obj) {
  for (int i = 0; i < as_ef_count; i++) if (as_ef_objs[i] == obj) return;
  if (as_ef_count == as_ef_cap) {
    as_ef_cap = as_ef_cap == 0 ? 8 : as_ef_cap * 2;
    as_ef_objs = (void**)realloc(as_ef_objs, (size_t)as_ef_cap * sizeof(void*));
  }
  as_ef_objs[as_ef_count++] = obj;
}
static void as_ef_unregister(void* obj) {
  EventDispatcher* d = (EventDispatcher*)obj;
  if (d->listeners != NULL) {
    as_value vc = as_listeners_get(d->listeners, "enterFrame", true);
    as_value vb = as_listeners_get(d->listeners, "enterFrame", false);
    if ((vc.tag == 6 && ((as_array*)vc.ptr)->length > 0) || (vb.tag == 6 && ((as_array*)vb.ptr)->length > 0)) return;
  }
  for (int i = 0; i < as_ef_count; i++) {
    if (as_ef_objs[i] == obj) { as_ef_objs[i] = as_ef_objs[--as_ef_count]; return; }
  }
}
#define AS_DISP_SNAP_SLOTS 8
static as_array* as_disp_snaps[AS_DISP_SNAP_SLOTS];
static int as_disp_snaps_reg = 0;
static int as_disp_depth = 0;
static bool as_disp_arr(as_array* arr, Event* evt) {
  int slot = as_disp_depth - 1;
  if (arr->length > 1 && slot >= 0 && slot < AS_DISP_SNAP_SLOTS) {
    if (!as_disp_snaps_reg) {
      as_disp_snaps_reg = 1;
      for (int i = 0; i < AS_DISP_SNAP_SLOTS; i++) gc_root_register((void**)&as_disp_snaps[i]);
    }
    as_array* snap = as_disp_snaps[slot];
    if (snap == NULL) { snap = as_array_new(); as_disp_snaps[slot] = snap; }
    snap->length = 0;
    for (int i = 0; i < arr->length; i++) as_array_push(snap, arr->data[i]);
    arr = snap;
  }
  bool ran = false;
  int n = arr->length;
  for (int i = 0; i < n; i++) {
    if (evt->immStopped) break;
    as_fn fn = (as_fn)as_v_obj_val(arr->data[i]);
    as_value arg[1];
    arg[0] = as_v_obj((void*)evt);
    fn->fn(fn->env, arg, 1);
    ran = true;
  }
  return ran;
}
static void* as_disp_parent(void* obj) { return (void*)((EventDispatcher*)obj)->parent; }
static bool as_disp_phase(Event* evt, void* current, bool capture) {
  EventDispatcher* d = (EventDispatcher*)current;
  evt->currentTarget = (Object*)current;
  if (d->listeners == NULL) return false;
  as_value v = as_listeners_get(d->listeners, evt->type, capture);
  if (v.tag == 6) return as_disp_arr((as_array*)v.ptr, evt);
  return false;
}
static bool as_disp_target(Event* evt, void* target) {
  evt->eventPhase = 2;
  evt->currentTarget = (Object*)target;
  EventDispatcher* d = (EventDispatcher*)target;
  if (d->listeners == NULL) return false;
  as_value vb = as_listeners_get(d->listeners, evt->type, false);
  if (vb.tag == 6) return as_disp_arr((as_array*)vb.ptr, evt);
  return false;
}

static void Event_ctor(Event* o, char* type, bool bubbles, bool cancelable) {
  o->type = type;
  gc_write_barrier((void*)type);
  o->bubbles = bubbles;
  o->cancelable = cancelable;
  o->target = NULL;
  o->currentTarget = NULL;
  o->eventPhase = 2;
  o->cancelled = false;
  o->propStopped = false;
  o->immStopped = false;
}
static Event* Event_new(char* type, bool bubbles, bool cancelable) {
  Event* o = (Event*)gc_alloc(GCT_CLASS, sizeof(Event));
  o->vtable = &Event_vt;
  Event_ctor(o, type, bubbles, cancelable);
  return o;
}
static char* Event_formatToString(void* _this, char* className, as_array* arguments) {
  char* out = as_str_concat("[", className);
  int n = (arguments != NULL) ? arguments->length : 0;
  for (int i = 0; i < n; i++) {
    char* name = as_v_str_val(as_array_get(arguments, i));
    out = as_str_concat(out, " ");
    out = as_str_concat(out, name);
    out = as_str_concat(out, "=");
    as_value v = as_dyn_get((void*)_this, name);
    if (v.tag == 3) { out = as_str_concat(out, "\""); out = as_str_concat(out, (char*)v.ptr); out = as_str_concat(out, "\""); }
    else out = as_str_concat(out, as_v_str_val(v));
  }
  return as_str_concat(out, "]");
}
static char* Event_toString(void* _this) {
  Event* e = (Event*)_this;
  char* r = as_str_alloc(128);
  snprintf(r, 128, "[Event type=\"%s\" bubbles=%s cancelable=%s eventPhase=%d]",
    e->type ? e->type : "", e->bubbles ? "true" : "false", e->cancelable ? "true" : "false", e->eventPhase);
  return r;
}
static Event* Event_clone(void* _this) {
  Event* e = (Event*)_this;
  Event* c = Event_new(e->type, e->bubbles, e->cancelable);
  c->target = e->target;
  return c;
}
static void Event_preventDefault(void* _this) { Event* e = (Event*)_this; if (e->cancelable) e->cancelled = true; }
static bool Event_isDefaultPrevented(void* _this) { return ((Event*)_this)->cancelled; }
static void Event_stopPropagation(void* _this) { ((Event*)_this)->propStopped = true; }
static void Event_stopImmediatePropagation(void* _this) { Event* e = (Event*)_this; e->propStopped = true; e->immStopped = true; }

static void EventDispatcher_ctor(EventDispatcher* o, Object* target) { o->listeners = NULL; o->parent = NULL; o->_evtarget = target; if (target != NULL) gc_write_barrier((void*)target); }
static EventDispatcher* EventDispatcher_new(Object* target) {
  EventDispatcher* o = (EventDispatcher*)gc_alloc(GCT_CLASS, sizeof(EventDispatcher));
  o->vtable = &EventDispatcher_vt;
  EventDispatcher_ctor(o, target);
  return o;
}
static void EventDispatcher_addEventListener(void* _this, char* type, as_fn listener, bool useCapture, int priority, bool useWeakReference) {
  (void)priority; (void)useWeakReference; // priority/weak-ref are accepted but not reordered in this subset
  EventDispatcher* d = (EventDispatcher*)_this;
  if (d->listeners == NULL) d->listeners = as_object_new();
  char* key = as_disp_key(type, useCapture);
  as_value v = as_object_get(d->listeners, key);
  as_array* arr;
  if (v.tag == 6) { arr = (as_array*)v.ptr; }
  else { arr = as_array_new(); as_object_set(d->listeners, key, as_v_arr((void*)arr)); }
  for (int i = 0; i < arr->length; i++) {
    as_fn a = (as_fn)as_v_obj_val(arr->data[i]);
    if (a->fn == listener->fn && a->env == listener->env) return;
  }
  as_array_push(arr, as_v_obj((void*)listener));
  if (strcmp(type, "enterFrame") == 0) as_ef_register(_this);
}
static void EventDispatcher_removeEventListener(void* _this, char* type, as_fn listener, bool useCapture) {
  EventDispatcher* d = (EventDispatcher*)_this;
  if (d->listeners == NULL) return;
  as_value v = as_listeners_get(d->listeners, type, useCapture);
  if (v.tag != 6) return;
  as_array* arr = (as_array*)v.ptr;
  for (int i = 0; i < arr->length; i++) {
    as_fn a = (as_fn)as_v_obj_val(arr->data[i]);
    if (a->fn == listener->fn && a->env == listener->env) {
      for (int j = i; j < arr->length - 1; j++) arr->data[j] = arr->data[j + 1];
      arr->length--;
      if (strcmp(type, "enterFrame") == 0) as_ef_unregister(_this);
      return;
    }
  }
}
static bool EventDispatcher_hasEventListener(void* _this, char* type) {
  EventDispatcher* d = (EventDispatcher*)_this;
  if (d->listeners == NULL) return false;
  as_value vc = as_listeners_get(d->listeners, type, true);
  as_value vb = as_listeners_get(d->listeners, type, false);
  return (vc.tag == 6 && ((as_array*)vc.ptr)->length > 0) || (vb.tag == 6 && ((as_array*)vb.ptr)->length > 0);
}
static bool EventDispatcher_willTrigger(void* _this, char* type) { return EventDispatcher_hasEventListener(_this, type); }
static bool EventDispatcher_dispatchEvent(void* _this, Event* event) {
  EventDispatcher* disp = (EventDispatcher*)_this;
  as_disp_depth++;
  void* own = disp->_evtarget != NULL ? disp->_evtarget : _this;
  Object* savedTarget = event->target;
  event->target = (Object*)own;
  void* ancestors[64];
  int anc_count = 0;
  for (void* p = as_disp_parent(own); p != NULL && anc_count < 64; p = as_disp_parent(p)) ancestors[anc_count++] = p;
  bool ran = false;
  event->eventPhase = 1; // CAPTURING (outermost -> target parent)
  for (int i = anc_count - 1; i >= 0; i--) { if (event->propStopped) break; if (as_disp_phase(event, ancestors[i], true)) ran = true; }
  if (!event->propStopped && as_disp_target(event, own)) ran = true;
  event->eventPhase = 3; // BUBBLING (target parent -> outermost)
  if (event->bubbles) { for (int i = 0; i < anc_count; i++) { if (event->propStopped) break; if (as_disp_phase(event, ancestors[i], false)) ran = true; } }
  if (!ran || savedTarget != NULL) event->target = savedTarget;
  as_disp_depth--;
  return !event->cancelled;
}

