  DisplayObjectContainer* o = (DisplayObjectContainer*)gc_alloc(GCT_CLASS, sizeof(DisplayObjectContainer));
  o->vtable = &DisplayObjectContainer_vt;
  DisplayObjectContainer_ctor(o);
  return o;
