static int as_on_stage(DisplayObject* o) {
  while (o->parent != NULL) o = (DisplayObject*)o->parent;
  return o->vtable != NULL && strcmp(o->vtable->cls_name, "Stage") == 0;
}
static void as_disp_stage_walk(DisplayObject* o, char* type) {
  if (o == NULL) return;
  EventDispatcher_dispatchEvent((void*)o, (Event*)Event_new(type, false, false));
  if (!as_is((void*)o, &DisplayObjectContainer_vt)) return;
  DisplayObjectContainer* c = (DisplayObjectContainer*)o;
  if (c->children == NULL) return;
  for (int i = 0; i < c->children->length; i++) as_disp_stage_walk((DisplayObject*)as_v_obj_val(c->children->data[i]), type);
}
static DisplayObject* DisplayObjectContainer_addChild(void* _this, DisplayObject* child) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL) c->children = as_array_new();
  if (child->parent != NULL) DisplayObjectContainer_removeChild((void*)child->parent, child);
  as_array_push(c->children, as_v_obj((void*)child));
  child->parent = (Object*)_this;
  EventDispatcher_dispatchEvent(child, Event_new((char*)"added", true, false));
  if (as_on_stage((DisplayObject*)_this)) as_disp_stage_walk(child, (char*)"addedToStage");
  return child;
}
static DisplayObject* DisplayObjectContainer_addChildAt(void* _this, DisplayObject* child, int index) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL) c->children = as_array_new();
  if (index < 0) index = 0;
  if (index > c->children->length) index = c->children->length;
  if (child->parent != NULL) DisplayObjectContainer_removeChild((void*)child->parent, child);
  as_array_ensure(c->children, c->children->length + 1);
  for (int i = c->children->length; i > index; i--) c->children->data[i] = c->children->data[i - 1];
  c->children->data[index] = as_v_obj((void*)child);
  gc_write_barrier_value(c->children->data[index]);
  c->children->length++;
  child->parent = (Object*)_this;
  EventDispatcher_dispatchEvent(child, Event_new((char*)"added", true, false));
  if (as_on_stage((DisplayObject*)_this)) as_disp_stage_walk(child, (char*)"addedToStage");
  return child;
}
static DisplayObject* DisplayObjectContainer_removeChild(void* _this, DisplayObject* child) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL) return NULL;
  int idx = -1;
  for (int i = 0; i < c->children->length; i++) if ((DisplayObject*)as_v_obj_val(c->children->data[i]) == child) { idx = i; break; }
  if (idx < 0) return NULL;
  int was_on_stage = as_on_stage(child);
  EventDispatcher_dispatchEvent(child, Event_new((char*)"removed", true, false));
  for (int i = 0; i < c->children->length; i++) {
    if ((DisplayObject*)as_v_obj_val(c->children->data[i]) != child) continue;
    for (int j = i; j < c->children->length - 1; j++) c->children->data[j] = c->children->data[j + 1];
    c->children->length--;
    break;
  }
  if (child->parent == (Object*)_this) child->parent = NULL;
  if (was_on_stage) as_disp_stage_walk(child, (char*)"removedFromStage");
  return child;
}
static DisplayObject* DisplayObjectContainer_removeChildAt(void* _this, int index) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL || index < 0 || index >= c->children->length) return NULL;
  return DisplayObjectContainer_removeChild(_this, (DisplayObject*)as_v_obj_val(c->children->data[index]));
}
static void DisplayObjectContainer_removeChildren(void* _this, int beginIndex, int endIndex) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL) return;
  if (beginIndex < 0) beginIndex = 0;
  if (endIndex > c->children->length) endIndex = c->children->length;
  for (int i = endIndex - 1; i >= beginIndex; i--) DisplayObjectContainer_removeChildAt(_this, i);
}
static int DisplayObjectContainer_getChildIndex(void* _this, DisplayObject* child) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children != NULL) for (int i = 0; i < c->children->length; i++) if ((DisplayObject*)as_v_obj_val(c->children->data[i]) == child) return i;
  as_throw(ArgumentError_new((char*)"Error #2025: The supplied DisplayObject must be a child of the caller.", 2025));
  return -1;
}
static DisplayObject* DisplayObjectContainer_getChildAt(void* _this, int index) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL || index < 0 || index >= c->children->length) return NULL;
  return (DisplayObject*)as_v_obj_val(c->children->data[index]);
}
static DisplayObject* DisplayObjectContainer_getChildByName(void* _this, char* name) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL) return NULL;
  for (int i = 0; i < c->children->length; i++) {
    DisplayObject* child = (DisplayObject*)as_v_obj_val(c->children->data[i]);
    if (child->name != NULL && strcmp(child->name, name) == 0) return child;
  }
  return NULL;
}
static bool DisplayObjectContainer_contains(void* _this, DisplayObject* child) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL) return false;
  for (int i = 0; i < c->children->length; i++) if ((DisplayObject*)as_v_obj_val(c->children->data[i]) == child) return true;
  return false;
}
static void DisplayObjectContainer_setChildIndex(void* _this, DisplayObject* child, int index) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  if (c->children == NULL) return;
  int cur = -1;
  for (int i = 0; i < c->children->length; i++) if ((DisplayObject*)as_v_obj_val(c->children->data[i]) == child) { cur = i; break; }
  if (cur < 0) return;
  if (index < 0) index = 0;
  if (index >= c->children->length) index = c->children->length - 1;
  if (cur == index) return;
  as_value v = c->children->data[cur];
  if (cur < index) { for (int i = cur; i < index; i++) c->children->data[i] = c->children->data[i + 1]; }
  else { for (int i = cur; i > index; i--) c->children->data[i] = c->children->data[i - 1]; }
  c->children->data[index] = v;
}
static int DisplayObjectContainer_get_numChildren(void* _this) {
  DisplayObjectContainer* c = (DisplayObjectContainer*)_this;
  return c->children == NULL ? 0 : c->children->length;
}

static DisplayObject* as_focus_obj = NULL;
static double as_tf_blink_t0 = 0.0;
static void as_tf_blink_reset(void) { as_tf_blink_t0 = as_now_ms(); }
static int as_tf_caret_on(void) {
  double now = as_now_ms();
  if (as_tf_blink_t0 <= 0.0) as_tf_blink_t0 = now;
  double dt = now - as_tf_blink_t0;
  if (dt < 0.0) dt = 0.0;
  return ((long)(dt / 500.0) % 2) == 0;
}
static DisplayObject* as_tab_anchor = NULL;
#define ASC_MOD_CTRL  1  /* KeyboardEvent.ctrlKey (Cmd counts as ctrl on macOS) */
#define ASC_MOD_ALT   2  /* altKey */
#define ASC_MOD_SHIFT 4  /* shiftKey */
#define ASC_MOD_CMD   8  /* the platform accelerator: Cmd on macOS, Ctrl elsewhere */
