static void as_focus_dispatch(DisplayObject* obj, char* type, Object* related) {
  if (obj == NULL) return;
  FocusEvent* fe = FocusEvent_new(type, true, false, related, false, 0);
  EventDispatcher_dispatchEvent((void*)obj, (Event*)fe);
}
static void as_set_focus(DisplayObject* obj) {
  if (obj == as_focus_obj) return;
  DisplayObject* old = as_focus_obj;
  as_focus_obj = obj;
  as_tf_blink_reset();
  as_focus_dispatch(old, (char*)"focusOut", (Object*)obj);
  as_focus_dispatch(obj, (char*)"focusIn", (Object*)old);
}
static void as_tab_scan(DisplayObject* o, int* ord, DisplayObject** tabs, int* tords, int* nt, int cap, int* focus_ord, int* anchor_ord) {
  if (o == NULL) return;
  int my = (*ord)++;
  if ((void*)o == (void*)as_focus_obj) *focus_ord = my;
  if ((void*)o == (void*)as_tab_anchor) *anchor_ord = my;
  if (as_is((void*)o, &InteractiveObject_vt) && ((InteractiveObject*)o)->tabEnabled && *nt < cap) {
    tabs[*nt] = o; tords[*nt] = my; (*nt)++;
  }
  if (as_is((void*)o, &DisplayObjectContainer_vt)) {
    DisplayObjectContainer* c = (DisplayObjectContainer*)o;
    if (c->children != NULL)
      for (int i = 0; i < c->children->length; i++)
        as_tab_scan((DisplayObject*)as_v_obj_val(c->children->data[i]), ord, tabs, tords, nt, cap, focus_ord, anchor_ord);
  }
}
static void as_focus_tab(DisplayObject* root, int dir) {
  DisplayObject* tabs[64];
  int tords[64];
  int ord = 0, nt = 0, focus_ord = -1, anchor_ord = -1;
  as_tab_scan((root != NULL) ? root : (DisplayObject*)ASC_root_stage, &ord, tabs, tords, &nt, 64, &focus_ord, &anchor_ord);
  if (nt <= 0) return;
  if (focus_ord < 0) focus_ord = anchor_ord; /* resume from the last mouse-focused object */
  int pick = -1;
  if (dir > 0) {
    for (int i = 0; i < nt; i++) if (tords[i] > focus_ord) { pick = i; break; }
    if (pick < 0) pick = 0; /* wrap to the first */
  } else {
    for (int i = nt - 1; i >= 0; i--) if (focus_ord < 0 || tords[i] < focus_ord) { pick = i; break; }
    if (pick < 0) pick = nt - 1; /* wrap to the last */
  }
  if (pick >= 0) as_set_focus(tabs[pick]);
}
static void as_focus_from_mouse_down(void* target) {
  DisplayObject* obj = NULL;
  if (target != NULL && as_is(target, &TextField_vt)) { obj = (DisplayObject*)target; as_tab_anchor = obj; }
  as_set_focus(obj);
}

static void as_tf_copy_selection(TextField* tf) {
  if (tf == NULL || tf->text == NULL) return;
  if (tf->displayAsPassword) return;
  int lo = tf->_sel_begin, hi = tf->_sel_end;
  if (lo < 0 || hi <= lo) return;
  int len = (int)strlen(tf->text);
  if (hi > len) hi = len;
  if (hi <= lo) return;
  char* buf = (char*)malloc((size_t)(hi - lo) + 1);
  if (buf == NULL) return;
  memcpy(buf, tf->text + lo, (size_t)(hi - lo));
  buf[hi - lo] = 0;
  as_clipboard_set_text(buf);
  free(buf);
}
static void as_tf_select_all(TextField* tf) {
  int len = (tf->text != NULL) ? (int)strlen(tf->text) : 0;
  tf->_sel_begin = 0; tf->_sel_end = len; tf->_sel_caret = len;
}

static bool as_tf_is_input(TextField* tf) {
  return tf != NULL && tf->type != NULL && strcmp(tf->type, "input") == 0;
}
static const char* as_tf_text(TextField* tf) { return tf->text != NULL ? tf->text : ""; }
static void as_tf_sel_range(TextField* tf, int* lo, int* hi) {
  int len = (int)strlen(as_tf_text(tf));
  int caret = tf->_sel_caret;
  if (caret < 0) caret = 0; if (caret > len) caret = len;
  int b = (tf->_sel_begin < 0 || tf->_sel_begin > len) ? caret : tf->_sel_begin;
  int e = (tf->_sel_end < 0 || tf->_sel_end > len) ? caret : tf->_sel_end;
  *lo = (b <= e) ? b : e; *hi = (b <= e) ? e : b;
}
static int as_tf_caret(TextField* tf) {
  int len = (int)strlen(as_tf_text(tf));
  int c = (tf->_sel_caret < 0) ? 0 : tf->_sel_caret;
  return c > len ? len : c;
}
static int as_tf_utf16_index(TextField* tf, int byteIndex) {
  const char* s = tf->text;
  if (s == NULL) return 0;
  int n = (int)strlen(s);
  if (byteIndex < 0) byteIndex = 0;
  if (byteIndex > n) byteIndex = n;
  if (tf->displayAsPassword) return byteIndex;
  int units = 0, i = 0;
  while (i < byteIndex) {
    unsigned char c = (unsigned char)s[i];
    if (c < 0x80) { i += 1; units += 1; }
    else if ((c & 0xE0) == 0xC0) { i += 2; units += 1; }
    else if ((c & 0xF0) == 0xE0) { i += 3; units += 1; }
    else if ((c & 0xF8) == 0xF0) { i += 4; units += 2; }
    else { i += 1; units += 1; }
  }
  return units;
}
static int as_tf_byte_index(TextField* tf, int unitIndex) {
  const char* s = tf->text;
  if (s == NULL || unitIndex <= 0) return 0;
  if (tf->displayAsPassword) { int m = (int)strlen(s); return unitIndex > m ? m : unitIndex; }
  int n = (int)strlen(s);
  int units = 0, i = 0;
  while (i < n && units < unitIndex) {
    unsigned char c = (unsigned char)s[i];
    if (c < 0x80) { i += 1; units += 1; }
    else if ((c & 0xE0) == 0xC0) { i += 2; units += 1; }
    else if ((c & 0xF0) == 0xE0) { i += 3; units += 1; }
    else if ((c & 0xF8) == 0xF0) { i += 4; units += 2; }
    else { i += 1; units += 1; }
  }
  return i > n ? n : i;
}
static void as_tf_set_caret(TextField* tf, int pos) {
  int len = (int)strlen(as_tf_text(tf));
  if (pos < 0) pos = 0; if (pos > len) pos = len;
  tf->_sel_begin = pos; tf->_sel_end = pos; tf->_sel_caret = pos;
  as_tf_blink_reset();
  tf->_goal_col = -1;
}
static void as_tf_extend_caret(TextField* tf, int pos) {
  int len = (int)strlen(as_tf_text(tf));
  if (pos < 0) pos = 0; if (pos > len) pos = len;
  int caret = as_tf_caret(tf);
  int anchor = caret;
  if (tf->_sel_begin >= 0 && tf->_sel_end >= 0 && tf->_sel_begin != tf->_sel_end) anchor = (caret == tf->_sel_begin) ? tf->_sel_end : tf->_sel_begin;
  if (anchor < 0) anchor = 0; if (anchor > len) anchor = len;
  if (pos <= anchor) { tf->_sel_begin = pos; tf->_sel_end = anchor; } else { tf->_sel_begin = anchor; tf->_sel_end = pos; }
  tf->_sel_caret = pos;
  as_tf_blink_reset();
  tf->_goal_col = -1;
}
static void as_tf_scroll_after_edit(TextField* tf);
static bool as_tf_splice(TextField* tf, int lo, int hi, const char* ins) {
  int len = (int)strlen(as_tf_text(tf));
  if (lo < 0) lo = 0; if (lo > len) lo = len;
  if (hi < lo) hi = lo; if (hi > len) hi = len;
  int insLen = (ins != NULL) ? (int)strlen(ins) : 0;
  if (tf->maxChars > 0) {
    int room = tf->maxChars - (len - (hi - lo));
    if (room < 0) room = 0;
    if (insLen > room) insLen = room;
  }
  if (insLen == 0 && hi <= lo) return false;
  char* out = as_str_alloc((size_t)(len - (hi - lo) + insLen) + 1);
  if (lo > 0) memcpy(out, as_tf_text(tf), (size_t)lo);
  if (insLen > 0) memcpy(out + lo, ins, (size_t)insLen);
  strcpy(out + lo + insLen, as_tf_text(tf) + hi);
  tf->text = out;
  gc_write_barrier((void*)out);
  as_skia_textlayout_delete(tf->_para); tf->_para = NULL; tf->_para_text = NULL;
  as_tf_set_caret(tf, lo + insLen);
  as_tf_scroll_after_edit(tf);
  return true;
}
static void as_tf_dispatch_change(TextField* tf) {
  EventDispatcher_dispatchEvent((void*)tf, (Event*)Event_new((char*)"change", true, false));
}
static int as_key_text_suppressed = 0;
static int ASC_ime_roi_valid = 0;
static double ASC_ime_roi[4] = {0.0, 0.0, 0.0, 0.0};
static bool as_tf_restrict_has(const char* p, unsigned char c) {
  int i = 0;
  while (p[i] != 0) {
    unsigned char a;
    if (p[i] == '\\' && p[i + 1] != 0) { a = (unsigned char)p[i + 1]; i += 2; }
    else { a = (unsigned char)p[i]; i++; }
    unsigned char b = a;
    if (p[i] == '-' && p[i + 1] != 0) {
      if (p[i + 1] == '\\' && p[i + 2] != 0) { b = (unsigned char)p[i + 2]; i += 3; }
      else { b = (unsigned char)p[i + 1]; i += 2; }
    }
    if (c >= a && c <= b) return true;
  }
  return false;
}
static int as_tf_restrict_char(const char* pat, unsigned char c) {
  if (pat == NULL) return (int)c;
  bool neg = (pat[0] == '^');
  const char* p = neg ? pat + 1 : pat;
  if (as_tf_restrict_has(p, c) != neg) return (int)c;
  unsigned char alt = c;
  if (c >= 'a' && c <= 'z') alt = (unsigned char)(c - 32);
  else if (c >= 'A' && c <= 'Z') alt = (unsigned char)(c + 32);
  if (alt == c) return 0;
  if (as_tf_restrict_has(p, alt) != neg) return (int)alt;
  return 0;
}
static void as_tf_insert_payload(TextField* tf, const char* payload, const char* text) {
  if (!as_tf_is_input(tf) || text == NULL) return;
  if (as_key_text_suppressed) { as_key_text_suppressed = 0; return; }
  TextEvent* te = TextEvent_new((char*)"textInput", true, true, (char*)(payload != NULL ? payload : text));
  EventDispatcher_dispatchEvent((void*)tf, (Event*)te);
  if (te->cancelled) return;
  const char* ins = text;
  char filtered[4096];
  if (tf->___restrict != NULL) {
    int fn = 0;
    int i = 0;
    while (text[i] != 0 && fn < (int)sizeof(filtered) - 1) {
      unsigned char c = (unsigned char)text[i];
      if (c == 13 || c == 10) filtered[fn++] = (char)c;
      else {
        int keep = as_tf_restrict_char(tf->___restrict, c);
        if (keep != 0) filtered[fn++] = (char)keep;
      }
      i++;
    }
    filtered[fn] = 0;
    ins = filtered;
  }
  int lo = 0, hi = 0;
  as_tf_sel_range(tf, &lo, &hi);
  if (as_tf_splice(tf, lo, hi, ins)) as_tf_dispatch_change(tf);
}
static void as_tf_insert_text(TextField* tf, const char* text) { as_tf_insert_payload(tf, text, text); }
static void as_tf_cut(TextField* tf) {
  if (!as_tf_is_input(tf)) return;
  if (tf->displayAsPassword) return;
  int lo = 0, hi = 0;
  as_tf_sel_range(tf, &lo, &hi);
  if (hi <= lo) return;
  as_tf_copy_selection(tf);
  if (as_tf_splice(tf, lo, hi, NULL)) as_tf_dispatch_change(tf);
}
static void as_tf_paste(TextField* tf) {
  if (!as_tf_is_input(tf)) return;
  char buf[4096];
  if (as_clipboard_get_text(buf, (int)sizeof(buf)) <= 0) return;
  as_tf_insert_text(tf, buf);
}
static void as_tf_delete(TextField* tf, int keyCode) {
  int len = (int)strlen(as_tf_text(tf));
  int lo = 0, hi = 0;
  as_tf_sel_range(tf, &lo, &hi);
  bool changed = false;
  if (hi > lo) changed = as_tf_splice(tf, lo, hi, NULL);
  else if (keyCode == 8) { if (lo > 0) changed = as_tf_splice(tf, lo - 1, lo, NULL); }
  else { if (lo < len) changed = as_tf_splice(tf, lo, lo + 1, NULL); }
  if (changed) as_tf_dispatch_change(tf);
}
static int as_tf_is_space(char c) { return c == 32 || c == 9 || c == 13 || c == 10; }
static int as_tf_word_left(const char* t, int pos) {
  int i = pos;
  while (i > 0 && !as_tf_is_space(t[i - 1])) i--;
  while (i > 0 && as_tf_is_space(t[i - 1])) i--;
  return i;
}
static void as_tf_word_select(TextField* tf, int idx) {
  const char* t = as_tf_text(tf);
  int len = (int)strlen(t);
  if (idx < 0) idx = 0;
  if (idx > len) idx = len;
  int lo = idx, hi = idx;
  while (lo > 0 && !as_tf_is_space(t[lo - 1])) lo--;
  while (hi < len && !as_tf_is_space(t[hi])) hi++;
  tf->_sel_begin = lo;
  tf->_sel_end = hi;
  tf->_sel_caret = hi;
}
static int as_tf_word_right(const char* t, int len, int pos) {
  int i = pos;
  while (i < len && !as_tf_is_space(t[i])) i++;
  while (i < len && as_tf_is_space(t[i])) i++;
  return i;
}
#define AS_TF_MAX_LINES 256
static void* as_tf_paragraph(TextField* tf);
static double as_tf_line_height(TextField* tf);
static int as_tf_visible_lines(TextField* tf);
static int as_tf_line_count(TextField* tf);
static int as_tf_line_table(TextField* tf, int* starts, int* ends, double* tops, int cap) {
  if (cap > AS_TF_MAX_LINES) cap = AS_TF_MAX_LINES;
  if (cap < 1) return 1;
  void* para = as_tf_paragraph(tf);
  if (para != NULL) {
    int n = as_skia_textlayout_line_metrics(para, starts, ends, tops, NULL, cap);
    if (n > 0) {
      for (int i = 0; i < n; i++) {
        if (starts != NULL) starts[i] = as_tf_byte_index(tf, starts[i]);
        if (ends != NULL) ends[i] = as_tf_byte_index(tf, ends[i]);
      }
      return n;
    }
  }
  const char* t = as_tf_text(tf);
  int len = (int)strlen(t);
  double lh = as_tf_line_height(tf);
  int n = 0, ls = 0;
  while (n < cap) {
    int le = ls;
    while (le < len && t[le] != 13 && t[le] != 10) le++;
    if (starts != NULL) starts[n] = ls;
    if (ends != NULL) ends[n] = le;
    if (tops != NULL) tops[n] = (double)n * lh;
    n++;
    if (le >= len) break;
    ls = le + 1;
  }
  return (n < 1) ? 1 : n;
}
static int as_tf_line_of_index(const int* starts, int n, int idx) {
  int k = 0;
  for (int i = 1; i < n; i++) { if (starts[i] <= idx) k = i; else break; }
  return k;
}
static int as_tf_line_end(const char* t, const int* starts, int n, int k, int len) {
  int le = (k + 1 < n) ? starts[k + 1] : len;
  if (le > starts[k] && (t[le - 1] == 13 || t[le - 1] == 10)) le--;
  return le;
}
static void as_tf_scroll_caret(TextField* tf, int line, int dir) {
  int vis = as_tf_visible_lines(tf);
  int n = as_tf_line_count(tf);
  int msv = n - vis + 1; if (msv < 1) msv = 1;
  int sv = tf->scrollV; if (sv < 1) sv = 1; if (sv > msv) sv = msv;
  if (dir > 0) sv = line + 1;
  else if (dir < 0) sv = line - vis + 2;
  else { if (line < sv - 1) sv = line + 1; else if (line > sv - 1 + vis - 1) sv = line - vis + 2; }
  if (sv < 1) sv = 1; if (sv > msv) sv = msv;
  tf->scrollV = sv;
}
static void as_tf_vmove(TextField* tf, int dir, int step, int page, bool shift) {
  if (step < 1) step = 1;
  if (!page && !tf->multiline) return;
  const char* t = as_tf_text(tf);
  int len = (int)strlen(t);
  int starts[AS_TF_MAX_LINES];
  int n = as_tf_line_table(tf, starts, NULL, NULL, AS_TF_MAX_LINES);
  int caret = as_tf_caret(tf);
  if (caret < 0) caret = 0; if (caret > len) caret = len;
  int cur = as_tf_line_of_index(starts, n, caret);
  int col = caret - starts[cur];
  if (page) tf->_goal_col = -1;
  if (tf->_goal_col >= 0) col = tf->_goal_col;
  int target = cur + dir * step;
  int pos = caret;
  if (target < 0) {
    if (!page) return;
    pos = 0;
  } else if (target >= n) {
    if (!page) return;
    pos = len;
  } else {
    int ls = starts[target];
    int le = as_tf_line_end(t, starts, n, target, len);
    int llen = le - ls; if (llen < 0) llen = 0;
    pos = ls + (col < llen ? col : llen);
  }
  if (shift) as_tf_extend_caret(tf, pos); else as_tf_set_caret(tf, pos);
  if (!page) tf->_goal_col = col;
  as_tf_scroll_caret(tf, as_tf_line_of_index(starts, n, pos), page ? dir : 0);
}
static void as_tf_line_ud(TextField* tf, int dir, bool shift) { as_tf_vmove(tf, dir, 1, 0, shift); }
static bool as_tf_is_edit_key(int kc) {
  return kc == 8 || kc == 33 || kc == 34 || kc == 35 || kc == 36 || kc == 37 || kc == 38 || kc == 39 || kc == 40 || kc == 46;
}
static void as_tf_edit_key(TextField* tf, int keyCode, int mod) {
  bool shift = (mod & ASC_MOD_SHIFT) != 0;
  if (keyCode == 8 || keyCode == 46) { as_tf_delete(tf, keyCode); return; }
  if (keyCode == 33 || keyCode == 34) { as_tf_vmove(tf, keyCode == 33 ? -1 : 1, as_tf_visible_lines(tf), 1, shift); return; }
  if (keyCode != 38 && keyCode != 40) tf->_goal_col = -1;
  int len = (int)strlen(as_tf_text(tf));
  int lo = 0, hi = 0;
  as_tf_sel_range(tf, &lo, &hi);
  int caret = as_tf_caret(tf);
  if (shift && keyCode == 36) {
    tf->_sel_begin = 0;
    tf->_sel_end = (hi > caret) ? hi : caret;
    return;
  }
  if (shift && keyCode == 35) {
    tf->_sel_begin = (lo < caret) ? lo : caret;
    tf->_sel_end = len;
    tf->_sel_caret = len;
    return;
  }
  int pos;
  if (keyCode == 36) pos = 0;
  else if (keyCode == 35) pos = len;
  else if ((mod & ASC_MOD_CMD) != 0 && keyCode == 37) pos = 0;
  else if ((mod & ASC_MOD_CMD) != 0 && keyCode == 39) pos = len;
  else if ((mod & ASC_MOD_ALT) != 0 && keyCode == 37) pos = as_tf_word_left(as_tf_text(tf), caret);
  else if ((mod & ASC_MOD_ALT) != 0 && keyCode == 39) pos = as_tf_word_right(as_tf_text(tf), len, caret);
  else if (keyCode == 37) pos = (hi > lo && !shift) ? lo : caret - 1;
  else if (keyCode == 39) pos = (hi > lo && !shift) ? hi : caret + 1;
  else { as_tf_line_ud(tf, keyCode == 38 ? -1 : 1, shift); return; }
  if (shift) as_tf_extend_caret(tf, pos); else as_tf_set_caret(tf, pos);
}

static void Stage_dispatchKey(void* _this, char* type, int keyCode, int charCode, int mod) {
  TextField* tf = NULL;
  if (as_focus_obj != NULL && as_is((void*)as_focus_obj, &TextField_vt)) tf = (TextField*)as_focus_obj;
  bool down = (strcmp(type, "keyDown") == 0);
  if (down && keyCode == 46 && (mod & ASC_MOD_SHIFT) != 0 && tf != NULL && as_tf_is_input(tf)) return;
  if ((mod & ASC_MOD_CMD) != 0 && tf != NULL && (keyCode == 65 || keyCode == 67 || keyCode == 86 || keyCode == 88)) {
    if (down) {
      if (keyCode == 65) { if (tf->selectable) as_tf_select_all(tf); }
      else if (keyCode == 67) { if (tf->selectable) as_tf_copy_selection(tf); }
      else if (keyCode == 88) { if (tf->selectable) as_tf_cut(tf); }
      else as_tf_paste(tf);
    }
    return;
  }
  if (!down && (mod & ASC_MOD_CMD) != 0 && keyCode != 15 && keyCode != 16 && keyCode != 17 && keyCode != 18) return;
  DisplayObject* target = (as_focus_obj != NULL) ? as_focus_obj : (DisplayObject*)_this;
  KeyboardEvent* evt = KeyboardEvent_new(type, true, down, charCode, keyCode, 0, (mod & ASC_MOD_CTRL) != 0, (mod & ASC_MOD_ALT) != 0, (mod & ASC_MOD_SHIFT) != 0, false, false, false);
  #ifdef __APPLE__
  evt->commandKey = (mod & ASC_MOD_CMD) != 0;
  #else
  evt->controlKey = (mod & ASC_MOD_CTRL) != 0;
  #endif
  EventDispatcher_dispatchEvent((void*)target, (Event*)evt);
  if (!down) return;
  as_key_text_suppressed = evt->cancelled ? 1 : 0;
  if (keyCode == 9 && !evt->cancelled) { as_focus_tab((DisplayObject*)_this, (mod & ASC_MOD_SHIFT) ? -1 : 1); return; }
  if (tf == NULL || !as_tf_is_input(tf)) return;
  if (as_tf_is_edit_key(keyCode)) as_tf_edit_key(tf, keyCode, mod);
  if (keyCode == 13 && tf->multiline) as_tf_insert_payload(tf, "\n", "\r");
}
static void as_tf_set_comp(TextField* tf, const char* text, int start, int length) {
  free(tf->_comp);
  tf->_comp = NULL;
  tf->_comp_start = -1;
  tf->_comp_len = 0;
  if (text == NULL || text[0] == 0) return;
  size_t n = strlen(text);
  char* c = (char*)malloc(n + 1);
  if (c == NULL) return;
  memcpy(c, text, n + 1);
  tf->_comp = c;
  tf->_comp_start = start;
  tf->_comp_len = length;
}
static void Stage_dispatchText(void* _this, char* text) {
  (void)_this;
  TextField* tf = NULL;
  if (as_focus_obj != NULL && as_is((void*)as_focus_obj, &TextField_vt)) tf = (TextField*)as_focus_obj;
  if (tf == NULL || !as_tf_is_input(tf)) return;
  as_tf_set_comp(tf, NULL, -1, 0);
  as_tf_insert_text(tf, text);
}

static InteractiveObject* Stage_get_focus(void* _this) { (void)_this; return (InteractiveObject*)as_focus_obj; }
static double as_tf_align_dx(TextField* tf);
static void as_rect_to_stage(DisplayObject* o, double* l, double* t, double* r, double* b);
static int TextField_get_maxScrollH(void* _this);
static void Stage_dispatchTextEditing(void* _this, char* text, int start, int length) {
  (void)_this;
  ASC_ime_roi_valid = 0;
  TextField* tf = NULL;
  if (as_focus_obj != NULL && as_is((void*)as_focus_obj, &TextField_vt)) tf = (TextField*)as_focus_obj;
  if (tf == NULL || !as_tf_is_input(tf)) return;
  as_tf_set_comp(tf, text, start, length);
  if (tf->_comp == NULL) return;
  void* para = as_tf_paragraph(tf);
  if (para == NULL) return;
  int at = as_tf_utf16_index(tf, as_tf_caret(tf));
  double cx = 0.0, cy = 0.0, ch = 0.0;
  if (!as_skia_textlayout_caret_rect(para, at, &cx, &cy, &ch)) return;
  double lh = as_tf_line_height(tf);
  int vis = as_tf_visible_lines(tf);
  int lc = as_tf_line_count(tf);
  int maxs = lc - vis + 1; if (maxs < 1) maxs = 1;
  int top = tf->scrollV; if (top < 1) top = 1; if (top > maxs) top = maxs;
  double scrollY = (double)(top - 1) * lh;
  int maxsh = TextField_get_maxScrollH((void*)tf);
  int leftpx = tf->_scroll_h;
  if (leftpx < 0) leftpx = 0; if (leftpx > maxsh) leftpx = maxsh;
  double alignDx = as_tf_align_dx(tf);
  double l = 2.0 + alignDx - (double)leftpx + cx;
  double t = 2.0 - scrollY + cy;
  double r = l + 2.0, b = t + ch;
  as_rect_to_stage((DisplayObject*)tf, &l, &t, &r, &b);
  ASC_ime_roi[0] = l; ASC_ime_roi[1] = t; ASC_ime_roi[2] = r; ASC_ime_roi[3] = b;
  ASC_ime_roi_valid = 1;
}

static void Stage_set_focus(void* _this, InteractiveObject* value) {
  (void)_this;
  as_set_focus((DisplayObject*)value);
}

static bool ASC_ime_enabled = true;
static char* ASC_ime_conversion_mode = (char*)"UNKNOWN";
static bool IME_get_enabled_static(void* _this) { (void)_this; return ASC_ime_enabled; }
static void IME_set_enabled_static(void* _this, bool value) { (void)_this; ASC_ime_enabled = value; }
static char* IME_get_conversionMode_static(void* _this) { (void)_this; return ASC_ime_conversion_mode; }
static void IME_set_conversionMode_static(void* _this, char* value) {
  (void)_this;
  if (value == NULL) { as_throw(Error_new((char*)"Error #2007: Parameter mode must be non-null.", 2007)); return; }
  if (strcmp(value, "ALPHANUMERIC_FULL") == 0) { ASC_ime_conversion_mode = (char*)"ALPHANUMERIC_FULL"; return; }
  if (strcmp(value, "ALPHANUMERIC_HALF") == 0) { ASC_ime_conversion_mode = (char*)"ALPHANUMERIC_HALF"; return; }
  if (strcmp(value, "CHINESE") == 0) { ASC_ime_conversion_mode = (char*)"CHINESE"; return; }
  if (strcmp(value, "JAPANESE_HIRAGANA") == 0) { ASC_ime_conversion_mode = (char*)"JAPANESE_HIRAGANA"; return; }
  if (strcmp(value, "JAPANESE_KATAKANA_FULL") == 0) { ASC_ime_conversion_mode = (char*)"JAPANESE_KATAKANA_FULL"; return; }
  if (strcmp(value, "JAPANESE_KATAKANA_HALF") == 0) { ASC_ime_conversion_mode = (char*)"JAPANESE_KATAKANA_HALF"; return; }
  if (strcmp(value, "KOREAN") == 0) { ASC_ime_conversion_mode = (char*)"KOREAN"; return; }
  as_throw(Error_new((char*)"Error #2063: Error attempting to execute IME command.", 2063));
}
static TextField* as_ime_target(void) {
  if (as_focus_obj == NULL || !as_is((void*)as_focus_obj, &TextField_vt)) return NULL;
  TextField* tf = (TextField*)as_focus_obj;
  if (!as_tf_is_input(tf)) return NULL;
  return tf;
}
static void IME_setCompositionString_static(char* composition) {
  TextField* tf = as_ime_target();
  if (tf == NULL) { as_throw(Error_new((char*)"Error #2063: Error attempting to execute IME command.", 2063)); return; }
  as_tf_set_comp(tf, composition, -1, 0);
}
static void IME_doConversion_static(void) {
  TextField* tf = as_ime_target();
  if (tf == NULL || tf->_comp == NULL) { as_throw(Error_new((char*)"Error #2063: Error attempting to execute IME command.", 2063)); return; }
  size_t n = strlen(tf->_comp);
  char* committed = (char*)malloc(n + 1);
  if (committed == NULL) { as_throw(Error_new((char*)"Error #2063: Error attempting to execute IME command.", 2063)); return; }
  memcpy(committed, tf->_comp, n + 1);
  as_tf_set_comp(tf, NULL, -1, 0);
  as_tf_insert_text(tf, committed);
  free(committed);
}
static void IME_compositionSelectionChanged_static(int start, int end) {
  TextField* tf = as_ime_target();
  if (tf == NULL || tf->_comp == NULL) { as_throw(Error_new((char*)"Error #2063: Error attempting to execute IME command.", 2063)); return; }
  tf->_comp_start = start;
  tf->_comp_len = end - start;
  if (tf->_comp_len < 0) tf->_comp_len = 0;
}
static void IME_compositionAbandoned_static(void) {
  TextField* tf = as_ime_target();
  if (tf != NULL) as_tf_set_comp(tf, NULL, -1, 0);
}
static IME* IME_new(void) { as_throw(Error_new((char*)"Error #2012: IME$ class cannot be instantiated.", 2012)); return NULL; }

