static void Timer__on_tick(void* obj) {
  Timer* o = (Timer*)obj;
  if (!o->running) return;
  o->currentCount++;
  if (o->repeatCount > 0 && o->currentCount >= o->repeatCount) o->running = false;
  EventDispatcher_dispatchEvent((void*)o, (Event*)TimerEvent_new((char*)"timer", false, false));
  if (o->repeatCount > 0 && o->currentCount >= o->repeatCount) { EventDispatcher_dispatchEvent((void*)o, (Event*)TimerEvent_new((char*)"timerComplete", false, false)); return; }
  if (o->running) as_rep_timer_add(o, o->delay, Timer__on_tick);
}
static void Timer_start(void* _this) { Timer* o = (Timer*)_this; if (o->running) return; o->running = true; as_rep_timer_add(o, o->delay, Timer__on_tick); }
static void Timer_stop(void* _this) { Timer* o = (Timer*)_this; o->running = false; as_rep_timer_cancel(o); }
static void Timer_reset(void* _this) { Timer* o = (Timer*)_this; o->running = false; as_rep_timer_cancel(o); o->currentCount = 0; }

