static void as_mc_goto(MovieClip* o, int f) {
  if (o->_tl_char != 0) {
    if (f <= 1 || f < o->currentFrame) as_swc_tl_rewind(o->_tl_char, (DisplayObject*)o, f);
    else if (f > o->currentFrame) as_swc_tl_apply(o->_tl_char, (DisplayObject*)o, f);
  }
  o->currentFrame = f;
}
static void MovieClip__on_frame(void* obj) { MovieClip* o = (MovieClip*)obj; if (!o->_playing) return; as_mc_goto(o, o->currentFrame >= o->totalFrames ? 1 : o->currentFrame + 1); }
static void MovieClip_play(void* _this) { MovieClip* o = (MovieClip*)_this; o->_playing = true; as_mc_add(o, MovieClip__on_frame); }
