static int as_mc_frame_of(MovieClip* o, as_value v) {
  if (o->_tl_char != 0 && v.tag == 3) {
    char* nm = as_v_str_val(v);
    int lb = as_swc_tl_labelframe(o->_tl_char, nm);
    if (lb != 0) return lb;
  }
  int n = (int)as_v_num_val(v);
  return n;
}
static void MovieClip_gotoAndPlay(void* _this, as_value frame) { MovieClip* o = (MovieClip*)_this; int f = as_mc_frame_of(o, frame); if (f < 1) f = 1; if (f > o->totalFrames) f = o->totalFrames; as_mc_goto(o, f); o->_playing = true; as_mc_add(o, MovieClip__on_frame); }
static void MovieClip_gotoAndStop(void* _this, as_value frame) { MovieClip* o = (MovieClip*)_this; int f = as_mc_frame_of(o, frame); if (f < 1) f = 1; if (f > o->totalFrames) f = o->totalFrames; as_mc_goto(o, f); o->_playing = false; as_mc_cancel(o); }
static void MovieClip_nextFrame(void* _this) { MovieClip* o = (MovieClip*)_this; as_mc_goto(o, o->currentFrame >= o->totalFrames ? 1 : o->currentFrame + 1); }
static void MovieClip_prevFrame(void* _this) { MovieClip* o = (MovieClip*)_this; as_mc_goto(o, o->currentFrame <= 1 ? o->totalFrames : o->currentFrame - 1); }
