static double SoundTransform__q(double v) { return (double)((long long)(v * 100.0)) / 100.0; }
static void SoundTransform__toChan(SoundTransform* t, double* vol, double* ltl, double* ltr, double* rtl, double* rtr) {
  if (t == NULL) { *vol = 1.0; *ltl = 1.0; *ltr = 0.0; *rtl = 0.0; *rtr = 1.0; return; }
  *vol = SoundTransform__q(t->_st_volume);
  *ltl = SoundTransform__q(t->_st_ltl);
  *ltr = SoundTransform__q(t->_st_ltr);
  *rtl = SoundTransform__q(t->_st_rtl);
  *rtr = SoundTransform__q(t->_st_rtr);
}
static SoundTransform* SoundTransform__fromChan(double vol, double ltl, double ltr, double rtl, double rtr) {
  SoundTransform* t = SoundTransform_new(vol, 0.0);
  t->_st_ltl = ltl; t->_st_ltr = ltr; t->_st_rtl = rtl; t->_st_rtr = rtr;
  return t;
}
