static void Sound_loadCompressedDataFromByteArray(void* _this, ByteArray* bytes, unsigned int length) {
  Sound* o = (Sound*)_this;
  unsigned int off = (bytes != NULL && bytes->position > 0) ? (unsigned int)bytes->position : 0u;
  unsigned int avail = (bytes != NULL && (int)bytes->length > (int)off) ? (unsigned int)bytes->length - off : 0u;
  if (length > avail) {
    as_throw(ArgumentError_new((char*)"Error #2084: The AMF encoding of the arguments cannot exceed 40K.", 2084));
    return;
  }
  unsigned int n = length;
  const unsigned char* src = (bytes != NULL) ? (const unsigned char*)bytes->data + off : NULL;
  if (bytes != NULL) bytes->position = (int)(off + n);
  o->_snd_buf = as_audio_decode(src, n);
  if (o->_snd_buf < 0) {
    o->_snd_bytesTotal = 0; o->_snd_bytesLoaded = 0;
    as_throw(ArgumentError_new((char*)"Error #2068: Invalid sound.", 2068));
    return;
  }
  o->_snd_bytesTotal = n; o->_snd_bytesLoaded = n; o->_snd_buffering = false; o->_snd_xpos = 0;
  Sound__applyID3(o, o->_snd_buf);
  EventDispatcher_dispatchEvent((void*)o, (Event*)Event_new((char*)"id3", false, false));
}
static void Sound_loadPCMFromByteArray(void* _this, ByteArray* bytes, unsigned int samples, char* format, bool stereo, double sampleRate) {
  Sound* o = (Sound*)_this;
  int chans = stereo ? 2 : 1;
  int rate = (sampleRate > 0.0) ? (int)sampleRate : 44100;
  int isShort = (format != NULL && strcmp(format, "short") == 0);
  if (!isShort && (format == NULL || strcmp(format, "float") != 0)) {
    as_throw(ArgumentError_new((char*)"Error #2005: Parameter  is of the incorrect type. Should be type .", 2005));
    return;
  }
  if (rate > 0.0 && ((double)samples / rate) > 1800.0) {
    as_throw(ArgumentError_new((char*)"Error #3767: The argument samples is too big. More than 1800 seconds of audio data is not permitted in a single call of loadPCMFromByteArray.", 3767));
    return;
  }
  if (bytes == NULL) { as_throw(ArgumentError_new((char*)"Error #2068: Invalid sound.", 2068)); return; }
  unsigned needBytes = (unsigned)samples * (unsigned)chans * (unsigned)(isShort ? 2 : 4);
  unsigned avail = (bytes->position > 0 && (unsigned)bytes->length > (unsigned)bytes->position) ? (unsigned)bytes->length - (unsigned)bytes->position : (bytes->position <= 0 ? (unsigned)bytes->length : 0u);
  if (needBytes > avail) {
    as_throw(ArgumentError_new((char*)"Error #2084: The AMF encoding of the arguments cannot exceed 40K.", 2084));
    return;
  }
  size_t need = (size_t)samples * (size_t)chans * 4u;
  float* pcm = (float*)malloc(need);
  if (pcm == NULL) { as_throw(ArgumentError_new((char*)"Error #2068: Invalid sound.", 2068)); return; }
  if (isShort) {
    for (size_t i = 0; i < (size_t)samples * (size_t)chans; i++) {
      pcm[i] = (float)(short)as_ba_get_u16(bytes) / 32768.0f;
    }
  } else {
    for (size_t i = 0; i < (size_t)samples * (size_t)chans; i++) {
      unsigned bits = as_ba_get_u32(bytes); float f; memcpy(&f, &bits, 4); pcm[i] = f;
    }
  }
  o->_snd_buf = as_audio_register_pcm(pcm, (long long)samples, chans, rate);
  free(pcm);
  if (o->_snd_buf < 0) { as_throw(ArgumentError_new((char*)"Error #2068: Invalid sound.", 2068)); return; }
  o->_snd_xpos = 0;
  o->_snd_bytesTotal = (unsigned int)need; o->_snd_bytesLoaded = (unsigned int)need; o->_snd_buffering = false;
  Sound__applyID3(o, o->_snd_buf);
}
static double Sound_extract(void* _this, ByteArray* target, double length, double startPosition) {
  Sound* o = (Sound*)_this;
  if (o->_snd_buf < 0 || target == NULL) return 0.0;
  long long frames = as_audio_buf_frames(o->_snd_buf);
  int srcc = as_audio_buf_channels(o->_snd_buf);
  if (srcc < 1) srcc = 1;
  long long start = (startPosition < 0.0) ? (long long)o->_snd_xpos : (long long)startPosition;
  long long want = (long long)length;
  if (want <= 0) return 0.0;
  if (start < 0) start = 0;
  if (start >= frames) { o->_snd_xpos = (int)frames; return 0.0; }
  if (start + want > frames) want = frames - start;
  o->_snd_xpos = (int)(start + want);
  const float* src = as_audio_buf_data(o->_snd_buf);
  as_ba_grow_pos(target, (int)(want * 2 * 4));
  for (long long i = 0; i < want; i++) {
    for (int c = 0; c < 2; c++) {
      float v = (srcc == 1) ? src[start + i] : src[(start + i) * srcc + c];
      unsigned bits; memcpy(&bits, &v, 4); as_ba_put_u32(target, bits);
    }
  }
  return (double)want;
}
