static SoundChannel* Sound_play(void* _this, double startTime, int loops, SoundTransform* transform) {
  Sound* o = (Sound*)_this;
  if (o->_snd_buf < 0) { as_throw(ArgumentError_new((char*)"Error #2068: Invalid sound.", 2068)); return NULL; }
  if (!as_audio_ready()) return NULL;
  double vol = 1.0, ltl = 1.0, ltr = 0.0, rtl = 0.0, rtr = 1.0;
  SoundTransform__toChan(transform, &vol, &ltl, &ltr, &rtl, &rtr);
  int voice = as_audio_play(o->_snd_buf, startTime, loops, vol, ltl, ltr, rtl, rtr);
  if (voice < 0) return NULL;
  SoundChannel* ch = SoundChannel_new();
  ch->_ch_voice = voice;
  ch->_ch_pos = startTime;
  ch->_ch_vol = vol; ch->_ch_ltl = ltl; ch->_ch_ltr = ltr; ch->_ch_rtl = rtl; ch->_ch_rtr = rtr;
  as_audio_chan_add((void*)ch, voice, SoundChannel__voiceDone);
  return ch;
}
static void SoundChannel__voiceDone(void* channel) {
  SoundChannel* ch = (SoundChannel*)channel;
  int voice = ch->_ch_voice;
  if (voice < 0) return;
  ch->_ch_pos = as_audio_buf_ms(as_audio_voice_buf(voice));
  ch->_ch_voice = -1;
  as_audio_voice_reap(voice);
  as_audio_chan_remove(voice);
  EventDispatcher_dispatchEvent((void*)ch, (Event*)Event_new((char*)"soundComplete", false, false));
}
