static void SoundMixer_stopAll_static(void) {
  for (int i = 0; i < AS_AUDIO_VOICES; i++) {
    void* p = as_audio_chan_at(i);
    if (p == NULL) continue;
    SoundChannel* ch = (SoundChannel*)p;
    ch->_ch_voice = -1; ch->_ch_pos = 0.0;
    as_audio_chan_remove(i);
  }
  as_audio_stop_all();
}
