static void SoundMixer_computeSpectrum_static(ByteArray* out, bool fftMode, int stretchFactor) {
  if (out == NULL) return;
  if (!as_audio_ready()) return;
  ByteArray_set_length(out, 2048u);
  memset(out->data, 0, 2048);
  out->position = 0;
  float scratch[512];
  as_audio_spectrum(scratch, fftMode ? 1 : 0, stretchFactor);
  for (int k = 0; k < 512; k++) { unsigned bits; memcpy(&bits, &scratch[k], 4); as_ba_put_u32(out, bits); }
  out->position = 0;
}
