static size_t as_url_domain_end(const char* url) {
  if (url == NULL) return 0;
  const char* p = url;
  const char* scheme = strstr(url, "://");
  if (scheme != NULL) p = scheme + 3;
  const char* slash = strchr(p, '/');
  return (slash == NULL) ? strlen(url) : (size_t)(slash - url);
}
static size_t as_url_dir_end(const char* url) {
  if (url == NULL) return 0;
  const char* last = strrchr(url, '/');
  return (last == NULL) ? 0 : (size_t)(last - url + 1);
}
static void URLRequest_useRedirectedURL(void* _this, URLRequest* sourceRequest, bool wholeURL, as_value pattern, char* replace) {
  URLRequest* o = (URLRequest*)_this;
  if (o->url == NULL || sourceRequest == NULL || sourceRequest->url == NULL) return;
  size_t keep = wholeURL ? as_url_dir_end(o->url) : as_url_domain_end(o->url);
  size_t take = wholeURL ? as_url_dir_end(sourceRequest->url) : as_url_domain_end(sourceRequest->url);
  char* head = as_str_alloc(take + 1);
  memcpy(head, sourceRequest->url, take); head[take] = '\0';
  char* out = as_str_concat(head, o->url + keep);
  if (pattern.tag == 3) { if (replace != NULL) out = as_str_replace(out, (char*)as_v_str_val(pattern), replace); }
  else if (as_v_is_inst(pattern, (void*)&RegExp_vt)) {
    RegExp* re = (RegExp*)pattern.ptr;
    if (replace != NULL && re->compiled != NULL && !re->compiled->err) out = as_str_replace_regex(out, re->compiled, replace, re->global);
  }
  o->url = out; gc_write_barrier((void*)out);
}

