static as_array* URLLoader__parseHeaders(const char* block) {
  as_array* arr = as_array_new();
  if (block == NULL) return arr;
  const char* p = block;
  while (*p != '\0') {
    const char* nl = p; while (*nl != '\0' && *nl != '\n') nl++;
    int n = (int)(nl - p); while (n > 0 && p[n - 1] == '\r') n--;
    if (n > 0) {
      char* line = as_str_alloc((size_t)n + 1);
      memcpy(line, p, (size_t)n); line[n] = '\0';
      char* colon = strchr(line, ':');
      if (colon != NULL) { *colon = '\0'; char* val = colon + 1; while (*val == ' ' || *val == '\t') val++; as_array_push(arr, as_v_obj((void*)URLRequestHeader_new(line, as_str_dup(val)))); }
    }
    p = (*nl == '\0') ? nl : nl + 1;
  }
  return arr;
}
static HTTPStatusEvent* URLLoader__httpStatusEvent(char* type, int status) {
  HTTPStatusEvent* e = HTTPStatusEvent_new(type, false, false, status);
  e->responseURL = NULL;
  e->responseHeaders = as_array_new(); gc_write_barrier((void*)e->responseHeaders);
  e->redirected = false;
  return e;
}
static HTTPStatusEvent* URLLoader__httpResponseEvent(char* type, int status, char* url, as_array* hdrs, bool redirected) {
  HTTPStatusEvent* e = HTTPStatusEvent_new(type, false, false, status);
  char* u = as_str_alloc(strlen(url) + 1); strcpy(u, url);
  e->responseURL = u; gc_write_barrier((void*)u);
  e->responseHeaders = hdrs; gc_write_barrier((void*)hdrs);
  e->redirected = redirected;
  return e;
}
typedef struct net_req { const char* method; const char* url; const char* headers; const void* body; size_t body_len; } net_req;
static void net__prepare_request(URLRequest* request, net_req* r) {
  r->method = (request->method != NULL) ? as_str_toUpper(request->method) : "GET";
  r->headers = (const char*)"";
  if (request->requestHeaders != NULL) {
    for (int i = 0; i < request->requestHeaders->length; i++) {
      URLRequestHeader* h = (URLRequestHeader*)as_v_obj_val(request->requestHeaders->data[i]);
      if (h == NULL || h->name == NULL) continue;
      char* line = as_str_concat(as_str_concat(h->name, (char*)": "), (h->value != NULL) ? h->value : (char*)"");
      r->headers = as_str_concat(as_str_concat((char*)r->headers, line), (char*)"\r\n");
    }
  }
  char* payload = NULL;
  const void* raw_body = NULL;
  size_t raw_body_len = 0;
  if (request->data.tag != 0 && request->data.tag != 5) {
    if (as_v_is_inst(request->data, &URLVariables_vt)) payload = URLVariables_toString(as_v_obj_val(request->data));
    else if (as_v_is_inst(request->data, &ByteArray_vt)) { ByteArray* b = (ByteArray*)as_v_obj_val(request->data); raw_body = (b != NULL) ? b->data : NULL; raw_body_len = (b != NULL) ? (size_t)b->length : 0; }
    else payload = as_v_str_val(request->data);
  }
  r->url = request->url;
  r->body = NULL;
  r->body_len = 0;
  if (strcmp(r->method, "GET") == 0) {
    if (payload != NULL) { const char* sep = (strchr(request->url, '?') != NULL) ? "&" : "?"; r->url = as_str_concat(as_str_concat(request->url, sep), payload); }
  } else {
    if (payload != NULL) { r->body = payload; r->body_len = strlen(payload); }
    else if (raw_body != NULL) { r->body = raw_body; r->body_len = raw_body_len; }
  }
}
