static void URLLoader__publish(URLLoader* o, const unsigned char* src, unsigned n, int binary) {
  if (binary) {
    ByteArray* ba = ByteArray_new();
    ba->data = (void*)gc_alloc(GCT_BYTES, (size_t)(n > 0 ? n : 1));
    ba->capacity = (int)n; ba->length = (int)n;
    if (n > 0) memcpy(ba->data, src, (size_t)n);
    gc_write_barrier((void*)ba->data);
    o->data = as_v_obj((void*)ba);
  } else if (o->dataFormat != NULL && strcmp(o->dataFormat, "variables") == 0) {
    char* vs = as_str_alloc((size_t)n + 1);
    if (n > 0) memcpy(vs, src, (size_t)n);
    vs[n] = '\0';
    o->data = as_v_obj((void*)URLVariables_new(vs));
  } else {
    char* s = as_str_alloc((size_t)n + 1);
    if (n > 0) memcpy(s, src, (size_t)n);
    s[n] = '\0';
    o->data = as_v_str(s);
  }
  gc_write_barrier_value(o->data);
}
static int URLLoader__isBinary(URLLoader* o) { return o->dataFormat != NULL && strcmp(o->dataFormat, "binary") == 0; }
static void Sound__finish(void* job);
static void as_net_pre_events(void* job) {
  void* obj = as_job_obj(job);
  if (obj == NULL) return;
  if (as_job_finish(job) == (void*)Sound__finish) {
    Sound* so = (Sound*)obj;
    if (so->_snd_url == NULL) {
      const char* fu = as_job_eff_url(job);
      if (fu[0] == 0) fu = so->_snd_requrl;
      so->_snd_url = (fu != NULL) ? as_job_strdup(fu) : NULL;
    }
  }
  if (!as_job_sent_open(job) && as_job_started(job)) {
    as_job_set_sent_open(job);
    EventDispatcher_dispatchEvent(obj, (Event*)Event_new((char*)"open", false, false));
  }
  if (!as_job_sent_status(job)) {
    int st = as_job_status(job);
    if (st > 0) {
      as_job_set_sent_status(job);
      as_array* hdrs = URLLoader__parseHeaders(as_job_headers(job));
      EventDispatcher_dispatchEvent(obj, (Event*)URLLoader__httpResponseEvent((char*)"httpResponseStatus", st, (char*)as_job_eff_url(job), hdrs, as_job_redirected(job) != 0));
    }
  }
  unsigned expected = as_job_expected_total(job);
  unsigned sent = as_job_marks_sent(job);
  unsigned mc = (unsigned)as_job_mark_count(job);
  while (sent < mc) {
    unsigned loaded = as_job_mark(job, (int)sent);
    sent++;
    as_job_set_marks_sent(job, sent);
    as_job_set_last_progress(job, loaded);
    EventDispatcher_dispatchEvent(obj, (Event*)ProgressEvent_new((char*)"progress", false, false, loaded, expected));
  }
}
static void URLLoader__finish(void* job) {
  URLLoader* o = (URLLoader*)as_job_obj(job);
  as_net_pre_events(job);
  if (as_job_failed(job)) {
    char* msg = as_job_error_text(job, (char*)"URLLoader: network URLs are not supported in this build (no HTTP backend linked; see docs/zh-cn/flash-net.md)", (char*)"URLLoader load failed");
    int eid = (as_job_error(job) == AS_JOB_ERR_UNSUPPORTED) ? 0 : 2032;
    if (eid != 0) msg = as_ioerror_text(as_job_path(job), eid, as_job_err_detail(job));
    EventDispatcher_dispatchEvent((void*)o, (Event*)URLLoader__httpStatusEvent((char*)"httpStatus", 0));
    URLLoader__publish(o, NULL, 0, URLLoader__isBinary(o));
    IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, msg);
    ev->errorID = eid;
    EventDispatcher_dispatchEvent((void*)o, (Event*)ev);
    return;
  }
  unsigned total = as_job_len(job);
  unsigned btotal = as_job_expected_total(job);
  if (total > 0 && (as_job_marks_sent(job) == 0 || as_job_last_progress(job) != total)) {
    as_job_set_last_progress(job, total);
    EventDispatcher_dispatchEvent((void*)o, (Event*)ProgressEvent_new((char*)"progress", false, false, total, btotal));
  }
  o->bytesLoaded = total; o->bytesTotal = btotal;
  URLLoader__publish(o, as_job_bytes(job), total, as_job_is_binary(job));
  int st = as_job_status(job);
  EventDispatcher_dispatchEvent((void*)o, (Event*)URLLoader__httpStatusEvent((char*)"httpStatus", st));
  if (st >= 300 && !EventDispatcher_hasEventListener((void*)o, (char*)"httpResponseStatus")) {
    IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, as_ioerror_text(as_job_path(job), 2032, NULL));
    ev->errorID = 2032;
    EventDispatcher_dispatchEvent((void*)o, (Event*)ev);
  } else {
    EventDispatcher_dispatchEvent((void*)o, (Event*)Event_new((char*)"complete", false, false));
  }
}
static void URLLoader_load(void* _this, URLRequest* request) {
  URLLoader* o = (URLLoader*)_this;
  o->data = as_v_null();
  o->bytesLoaded = 0; o->bytesTotal = 0;
  if (request == NULL) as_throw(TypeError_new((char*)"Error #2007: Parameter request must be non-null.", 2007));
  if (request->url == NULL) as_throw(TypeError_new((char*)"Error #2007: Parameter url must be non-null.", 2007));
  const char* url = request->url;
  int binary = (o->dataFormat != NULL && strcmp(o->dataFormat, "binary") == 0);
  if (strncmp(url, "http://", 7) == 0 || strncmp(url, "https://", 8) == 0) {
    net_req r; net__prepare_request(request, &r);
    void* j = as_async_submit_http((void*)o, URLLoader__finish, (char*)r.url, r.method, request->userAgent, request->contentType, (char*)r.headers, r.body, r.body_len, binary, request->followRedirects ? 1 : 0, request->idleTimeout, request->manageCookies ? 1 : 0);
    if (j != NULL) as_job_set_net_events(j);
  return;
  }
  const char* path = url;
  if (strncmp(path, "file://", 7) == 0) path += 7;
  void* j = as_async_submit(binary ? AS_JOB_READ_BYTES : AS_JOB_READ_TEXT, (void*)o, URLLoader__finish, path, NULL, binary);
  if (j != NULL) as_job_set_net_events(j);
}
static void URLLoader_close(void* _this) {
  URLLoader* o = (URLLoader*)_this;
  if (!as_async_cancel((void*)o)) as_throw(Error_new((char*)"Error #2029: This URLStream object does not have a stream opened.", 2029));
}

static void Sound__finish(void* job) {
  Sound* o = (Sound*)as_job_obj(job);
  as_net_pre_events(job);
  if (as_job_failed(job)) {
    char* msg = as_job_error_text(job, (char*)"Sound.load: network URLs are not supported in this build (no HTTP backend linked)", (char*)"Sound load failed");
    int eid = (as_job_error(job) == AS_JOB_ERR_UNSUPPORTED) ? 0 : 2032;
    if (eid != 0) msg = as_ioerror_text(as_job_path(job), eid, as_job_err_detail(job));
    IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, msg);
    ev->errorID = eid;
    EventDispatcher_dispatchEvent((void*)o, (Event*)ev);
    return;
  }
  const char* finalurl = as_job_eff_url(job);
  if (finalurl[0] == 0) finalurl = o->_snd_requrl;
  o->_snd_url = (finalurl != NULL) ? as_job_strdup(finalurl) : NULL;
  unsigned total = as_job_total(job);
  unsigned btotal = as_job_expected_total(job);
  if (as_job_marks_sent(job) == 0) {
    as_job_set_marks_sent(job, 1);
    EventDispatcher_dispatchEvent((void*)o, (Event*)ProgressEvent_new((char*)"progress", false, false, 0, btotal));
  }
  if (total > 0 && (as_job_marks_sent(job) <= 1 || as_job_last_progress(job) != total)) {
    as_job_set_last_progress(job, total);
    EventDispatcher_dispatchEvent((void*)o, (Event*)ProgressEvent_new((char*)"progress", false, false, total, btotal));
  }
  o->_snd_bytesTotal = btotal;
  o->_snd_bytesLoaded = total;
  o->_snd_buf = as_audio_decode(as_job_bytes(job), total);
  if (o->_snd_buf < 0) {
    int eid = 2032;
    IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, as_ioerror_text(as_job_path(job), eid, NULL));
    ev->errorID = eid;
    EventDispatcher_dispatchEvent((void*)o, (Event*)ev);
    return;
  }
  Sound__applyID3(o, o->_snd_buf);
  EventDispatcher_dispatchEvent((void*)o, (Event*)Event_new((char*)"complete", false, false));
}
static void Sound_load(void* _this, URLRequest* stream, SoundLoaderContext* context) {
  Sound* o = (Sound*)_this;
  (void)context;
  o->_snd_buffering = true;
  o->_snd_bytesLoaded = 0; o->_snd_bytesTotal = 0;
  if (stream == NULL) { as_throw(TypeError_new((char*)"Error #2007: Parameter stream must be non-null.", 2007)); return; }
  if (stream->url == NULL) { as_throw(TypeError_new((char*)"Error #2007: Parameter url must be non-null.", 2007)); return; }
  const char* url = stream->url;
  o->_snd_requrl = as_job_strdup(url);
  if (strncmp(url, "http://", 7) == 0 || strncmp(url, "https://", 8) == 0) {
    net_req r; net__prepare_request(stream, &r);
    void* j = as_async_submit_http((void*)o, Sound__finish, (char*)r.url, r.method, stream->userAgent, stream->contentType, (char*)r.headers, r.body, r.body_len, 1, stream->followRedirects ? 1 : 0, stream->idleTimeout, stream->manageCookies ? 1 : 0);
    if (j != NULL) as_job_set_net_events(j);
    return;
  }
  const char* path = url;
  if (strncmp(path, "file://", 7) == 0) path += 7;
  void* j = as_async_submit(AS_JOB_READ_BYTES, (void*)o, Sound__finish, path, NULL, 1);
  if (j != NULL) as_job_set_net_events(j);
}
static void Sound_close(void* _this) {
  if (!as_async_cancel((void*)_this)) as_throw(Error_new((char*)"Error #2029: This URLStream object does not have a stream opened.", 2029));
}

