static void Socket__invalid(void) { as_throw(IOError_new((char*)"Error #2002: Operation attempted on invalid socket.", 2002)); }
static void Socket__eof(void) { as_throw(EOFError_new((char*)"Error #2030: End of file was encountered.", 2030)); }
static int Socket__live(void* o) { as_sock* s = (as_sock*)((Socket*)o)->_sock; if (s == NULL) return 0; int st = as_sock_state_of(s); return !as_sock_is_dead(s) && (st == AS_SOCK_CONNECTING || st == AS_SOCK_CONNECTED); }
static int Socket__connected(void* o) { as_sock* s = (as_sock*)((Socket*)o)->_sock; return s != NULL && !as_sock_is_dead(s) && as_sock_state_of(s) == AS_SOCK_CONNECTED; }
static int Socket__avail(void* o) { as_sock* s = (as_sock*)((Socket*)o)->_sock; return s == NULL ? 0 : as_sock_avail(s); }
static int Socket__read(void* o, void* dst, int n) { as_sock* s = (as_sock*)((Socket*)o)->_sock; return s == NULL ? 0 : as_sock_read(s, dst, n); }
static int Socket__need(void* o, int n) { if (!Socket__live(o)) { Socket__invalid(); return 0; } return Socket__avail(o) >= n; }
