    Socket__read(_this, buf, 4);
    if (Socket__little(_this)) { unsigned char r[4]; for (int i = 0; i < 4; i++) r[i] = buf[3 - i]; memcpy(&f, r, 4); }
    else memcpy(&f, buf, 4);
