static char* Socket_readUTFBytes(void* _this, unsigned length) { return Socket__str((Socket*)_this, (int)length); }
// readUTF: an unsigned 16-bit byte count, then that many bytes.
static char* Socket_readUTF(void* _this) {
    Socket* o = (Socket*)_this;
    unsigned n = (unsigned)Socket__uint(o, 2, 0);
    return Socket__str(o, (int)n);
}
// readMultiByte decodes with the named charset through the shared codec
