static void Socket_writeUTFBytes(void* _this, char* value) {
    if (value == NULL) value = (char*)"";
    Socket__write(_this, value, (int)strlen(value));
}
// writeUTF prefixes the byte count. Like ByteArray.writeUTF in this subset, a
