static void XMLSocket_send(void* _this, as_value object) {
    XMLSocket* o = (XMLSocket*)_this;
    if (!XMLSocket_get_connected(o)) { Socket__invalid(); return; }
    if (object.tag == 0 || object.tag == 5) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }
    char* text = as_coerce_str(object);
    if (text == NULL) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }
    as_sock* s = (as_sock*)o->_sock;
    int n = (int)strlen(text);
    if (n > 0) as_sock_write(s, text, n);
    as_sock_write(s, "", 1);
    as_sock_try_flush(s);
}
static int XMLSocket__deliver(XMLSocket* o) {
    int sent = 0;
    for (;;) {
        as_sock* s = (as_sock*)o->_sock;
        if (s == NULL) break;
        int at = as_sock_index_of(s, 0);
        if (at < 0) break;
        char* msg = as_str_alloc((size_t)at + 1);
        if (at > 0) as_sock_read(s, msg, at);
        msg[at] = '\0';
        unsigned char nul = 0;
        as_sock_read(s, &nul, 1);
        EventDispatcher_dispatchEvent((void*)o, (Event*)DataEvent_new((char*)"data", false, false, msg));
        sent++;
        if (as_sock_is_dead(s)) break;
    }
    return sent;
}

