static IOErrorEvent* Socket__ioerror_event(const char* url) {
    IOErrorEvent* e = IOErrorEvent_new((char*)"ioError", false, false, Socket__ioerror_text(url));
    e->errorID = 2031;
    return e;
}
static char* Socket__ioerror_text(const char* url) {
    size_t n = strlen(url == NULL ? "" : url) + 48;
    char* t = as_str_alloc(n);
    snprintf(t, n, "Error #2031: Socket Error. URL: %s", url == NULL ? "" : url);
    return t;
}
static int as_sock_dispatch(void) {
    int total = 0;
    as_sock_dispatching = 1;
    int n = as_sock_count_all();
    for (int i = 0; i < n; i++) {
        as_sock* s = as_sock_at(i);
        if (as_sock_is_dead(s)) continue;
        int ev = as_sock_events_of(s);
        void* obj = as_sock_obj_of(s);
        if (obj == NULL) continue;
        if (ev & AS_SOCK_EV_CONNECT) {
            as_sock_clear_events(s, AS_SOCK_EV_CONNECT);
            EventDispatcher_dispatchEvent(obj, (Event*)Event_new((char*)"connect", false, false));
            total++;
            if (as_sock_is_dead(s)) continue;
            ev = as_sock_events_of(s);
        }
        if (ev & AS_SOCK_EV_ACCEPT) {
            as_sock_clear_events(s, AS_SOCK_EV_ACCEPT);
            as_sock* c = as_sock_take_accepted(s);
            if (c != NULL) {
                Socket* peer = Socket_new(NULL, 0);
                peer->_sock = (void*)c;
                as_sock_set_obj(c, (void*)peer);
                // ONE event, a ServerSocketConnectEvent: its type is
                // ServerSocketConnectEvent.CONNECT === Event.CONNECT === "connect"
                // and it extends Event, so a single dispatch reaches listeners
                // registered for either constant (measured on adl).
                EventDispatcher_dispatchEvent(obj, (Event*)ServerSocketConnectEvent_new((char*)"connect", false, false, peer));
                total++;
            }
            if (as_sock_is_dead(s)) continue;
            ev = as_sock_events_of(s);
        }
        if (ev & AS_SOCK_EV_DATA) {
            as_sock_clear_events(s, AS_SOCK_EV_DATA);
            if (as_is(obj, &XMLSocket_vt)) {
                total += XMLSocket__deliver((XMLSocket*)obj);
            } else {
                // bytesTotal stays 0: a socket has no declared length (measured).
                EventDispatcher_dispatchEvent(obj, (Event*)ProgressEvent_new((char*)"socketData", false, false, (unsigned)as_sock_avail(s), 0));
                total++;
            }
            if (as_sock_is_dead(s)) continue;
            ev = as_sock_events_of(s);
        }
        if (ev & AS_SOCK_EV_OUTPUT) {
            as_sock_clear_events(s, AS_SOCK_EV_OUTPUT);
            if (!as_is(obj, &XMLSocket_vt)) {
                EventDispatcher_dispatchEvent(obj, (Event*)OutputProgressEvent_new((char*)"outputProgress", false, false, (double)as_sock_pending(s), 0.0));
                total++;
            }
            if (as_sock_is_dead(s)) continue;
            ev = as_sock_events_of(s);
        }
        if (ev & AS_SOCK_EV_ERROR) {
            as_sock_clear_events(s, AS_SOCK_EV_ERROR);
            EventDispatcher_dispatchEvent(obj, (Event*)Socket__ioerror_event(as_sock_url(s)));
            total++;
            if (as_sock_is_dead(s)) continue;
            ev = as_sock_events_of(s);
        }
        if (ev & AS_SOCK_EV_CLOSE) {
            as_sock_clear_events(s, AS_SOCK_EV_CLOSE);
            EventDispatcher_dispatchEvent(obj, (Event*)Event_new((char*)"close", false, false));
            total++;
        }
    }
    as_sock_dispatching = 0;
    as_sock_reap();
    return total;
}

static void URLVariables_ctor(URLVariables* o, char* source) {
  Object_ctor((Object*)o);
  o->_dyn = as_object_new();
  gc_write_barrier((void*)o->_dyn);
  URLVariables_decode((void*)o, source);
}
static URLVariables* URLVariables_new(char* source) { URLVariables* o = (URLVariables*)gc_alloc(GCT_CLASS, sizeof(URLVariables)); o->vtable = &URLVariables_vt; URLVariables_ctor(o, source); return o; }
static void URLVariables_decode(void* _this, char* source) {
  URLVariables* o = (URLVariables*)_this;
  if (source == NULL || *source == '\0') return;
  char* s = as_str_alloc(strlen(source) + 1);
  strcpy(s, source);
  char* p = s;
  while (*p != '\0') {
    char* eq = strchr(p, '=');
    char* amp = strchr(p, '&');
    if (eq == NULL || (amp != NULL && amp < eq)) break;
    *eq = '\0';
    char* val = eq + 1;
    if (amp != NULL) { *amp = '\0'; amp++; }
    as_object_set(o->_dyn, as_url_decode(p), as_v_str(as_url_decode(val)));
    if (amp == NULL) break;
    p = amp;
  }
}
static char* URLVariables_toString(void* _this) {
  URLVariables* o = (URLVariables*)_this;
  as_object* d = o->_dyn;
  if (d == NULL || d->length == 0) return (char*)"";
  size_t total = 0;
  for (int i = 0; i < d->length; i++) total += as_url_encoded_len(d->keys[i]) + as_url_encoded_len(as_v_str_val(d->vals[i])) + 2;
  char* out = as_str_alloc(total + 1);
  char* p = out;
  for (int i = 0; i < d->length; i++) {
    p += as_url_encode_into(p, d->keys[i]);
    *p++ = '=';
    p += as_url_encode_into(p, as_v_str_val(d->vals[i]));
    if (i < d->length - 1) *p++ = '&';
  }
  *p = '\0';
  return out;
}

