static bool File_get_exists(void* _this) { File* o = (File*)_this; return o->nativePath != NULL && as_path_exists(o->nativePath); }
static bool File_get_isDirectory(void* _this) { File* o = (File*)_this; return o->nativePath != NULL && as_path_is_dir(o->nativePath); }
static double File_get_size(void* _this) { File* o = (File*)_this; if (o->nativePath == NULL) return 0.0; struct stat st; if (stat(o->nativePath, &st) != 0) return 0.0; return (double)st.st_size; }
static double as_file_space_available(const char* p) {
  if (p == NULL) return 0.0;
  #ifndef _WIN32
    { struct stat st; if (stat(p, &st) != 0) return 0.0; if (!S_ISDIR(st.st_mode) && !S_ISREG(st.st_mode)) return 0.0; }
  #endif
  #ifdef _WIN32
    // GetDiskFreeSpaceEx asks for a DIRECTORY, so a path naming a regular file must
    // be mapped to the volume that holds it first -- GetVolumePathName answers for
    // either kind of path, which is what makes a file report the same figure as the
    // directory containing it (measured: adl does exactly that on Windows). The
    // existence gate is what keeps a path the OS cannot resolve at 0: GetVolumePath
    // Name walks UP to the nearest mounted ancestor, so without it an unresolvable
    // path would report its volume figure instead (measured: adl reports 0).
    if (!as_path_exists(p)) return 0.0;
    char root[MAX_PATH];
    if (!GetVolumePathNameA(p, root, MAX_PATH)) return 0.0;
    ULARGE_INTEGER freeAvail;
    freeAvail.QuadPart = 0;
    if (!GetDiskFreeSpaceExA(root, &freeAvail, NULL, NULL)) return 0.0;
    return (double)freeAvail.QuadPart;
  #elif !defined(__wasi__) && !defined(__EMSCRIPTEN__)
    struct statvfs sv;
    if (statvfs(p, &sv) != 0) return 0.0;
    return (double)sv.f_bavail * (double)sv.f_frsize;
  #else
    return 0.0;
  #endif
}
static double File_get_spaceAvailable(void* _this) { File* o = (File*)_this; return as_file_space_available(o->nativePath); }
static char* File_get_name(void* _this) {
  File* o = (File*)_this;
  if (o->nativePath == NULL) return (char*)"";
  const char* s = o->nativePath;
  int n = (int)strlen(s);
  while (n > 1 && (s[n - 1] == '/' || s[n - 1] == '\\')) n--;
  int start = 0;
  for (int i = n - 1; i >= 0; i--) if (s[i] == '/' || s[i] == '\\') { start = i + 1; break; }
  char* out = as_str_alloc((size_t)(n - start) + 1);
  memcpy(out, s + start, (size_t)(n - start));
  out[n - start] = '\0';
  return out;
}
static char* File_get_extension(void* _this) {
  File* o = (File*)_this;
  if (o->nativePath == NULL) return (char*)"";
  const char* s = o->nativePath;
  int n = (int)strlen(s);
  while (n > 1 && (s[n - 1] == '/' || s[n - 1] == '\\')) n--;
  int base = 0;
  for (int i = n - 1; i >= 0; i--) if (s[i] == '/' || s[i] == '\\') { base = i + 1; break; }
  int dot = -1;
  for (int i = n - 1; i > base; i--) if (s[i] == '.') { dot = i; break; }
  if (dot < 0) return (char*)"";
  char* out = as_str_alloc((size_t)(n - dot - 1) + 1);
  memcpy(out, s + dot + 1, (size_t)(n - dot - 1));
  out[n - dot - 1] = '\0';
  return out;
}
static char* File_get_type(void* _this) {
  char* ext = File_get_extension(_this);
  int n = (int)strlen(ext);
  if (n == 0) return (char*)"";
  char* out = as_str_alloc((size_t)n + 2);
  out[0] = '.';
  for (int i = 0; i < n; i++) {
    char c = ext[i];
    if (c >= 'A' && c <= 'Z') c = (char)(c + 32);
    out[i + 1] = c;
  }
  out[n + 1] = '\0';
  return out;
}
static File* File_get_parent(void* _this) {
  File* o = (File*)_this;
  if (o->nativePath == NULL) return NULL;
  const char* s = o->nativePath;
  int n = (int)strlen(s);
  while (n > 1 && (s[n - 1] == '/' || s[n - 1] == '\\')) n--;
  int cut = -1;
  for (int i = n - 1; i > 0; i--) if (s[i] == '/' || s[i] == '\\') { cut = i; break; }
  if (cut <= 0) return NULL;
  char* out = as_str_alloc((size_t)cut + 1);
  memcpy(out, s, (size_t)cut);
  out[cut] = '\0';
  return File_new(out);
}
static bool File_get_isHidden(void* _this) {
  File* o = (File*)_this;
  if (o->nativePath == NULL) return false;
  const char* base = o->nativePath;
  for (const char* p = o->nativePath; *p; p++) if (*p == '/' || *p == '\\') base = p + 1;
  return base[0] == '.';
}
static File* File_resolvePath(void* _this, char* path) { File* o = (File*)_this; return (o->nativePath == NULL) ? File_new(path) : File_new(as_path_join(o->nativePath, path)); }
static void File_createDirectory(void* _this) { File* o = (File*)_this; if (o->nativePath != NULL) as_mkdirs(o->nativePath); }
static void File_deleteFile(void* _this) { File* o = (File*)_this; if (o->nativePath != NULL) remove(o->nativePath); }
static void File_deleteDirectory(void* _this) { File* o = (File*)_this; if (o->nativePath != NULL) as_rmdir_one(o->nativePath); }
// Measured against adl 51.4.1 on macOS 26 (temp/trashprobe/):
//   * moveToTrash() is declared VOID, not Boolean -- f.moveToTrash().toString()
//     is a compile error in mxmlc, and adl evaluates the call to undefined.
//   * a path that does not exist throws Error #3003 "File or directory does not
//     exist."; a filesystem refusal (EPERM on the parent directory) throws #2038
//     "File I/O Error."; a File with no nativePath throws #2037.
//   * after a successful move nativePath is UNCHANGED and exists becomes false:
//     the receiver keeps denoting the old location, it is not rewritten.
//   * trashing a path that already sits in the trash directory is a successful
//     no-op -- adl leaves the item where it is.
//   * moveToTrashAsync() never throws for those failures: a missing path
//     dispatches IOErrorEvent(ioError, errorID 3003), success dispatches
//     Event.COMPLETE, and only the empty-File case throws #2037.
// The directory is the one Finder uses, so the item appears in the Trash under
// its own name and stays restorable: ~/.Trash on the home volume,
// <volume root>/.Trashes/<uid> on another volume. Plain POSIX uses the
// freedesktop.org layout ($XDG_DATA_HOME/Trash/{files,info} plus a .trashinfo
// sidecar beside each payload) so a Linux desktop can put it back. Windows has
// no such directory to rename into -- its trash is the shell's Recycle Bin, a
// per-user store of $I<id>/$R<id> pairs reachable only through SHFileOperationW
// -- so that host takes the separate as_trash_move_shell path below (measured:
// adl 51.4.1 really does recycle the item there rather than erase it).
// as_path_basename: a fresh string with the last component of `path` (trailing
// separators ignored), or NULL when the path names no component ("/").
static char* as_path_basename(const char* p) {
  if (p == NULL) return NULL;
  size_t n = strlen(p);
  while (n > 1 && (p[n - 1] == '/' || p[n - 1] == '\\')) n--;
  size_t start = 0;
  for (size_t i = 0; i < n; i++) if (p[i] == '/' || p[i] == '\\') start = i + 1;
  if (start >= n) return NULL;
  char* out = as_str_alloc(n - start + 1);
  memcpy(out, p + start, n - start);
  out[n - start] = '\0';
  return out;
}

// as_volume_root: the mount point that owns `path`. POSIX has no portable
// "which mount is this" call, so walk up while st_dev stays the same; the last
// directory that still shares the path's device is the volume root.
static char* as_volume_root(const char* path) {
  struct stat st;
  if (path == NULL || stat(path, &st) != 0) return NULL;
  dev_t dev = st.st_dev;
  char* cur = as_str_alloc(strlen(path) + 2);
  strcpy(cur, path);
  size_t n = strlen(cur);
  while (n > 1 && (cur[n - 1] == '/' || cur[n - 1] == '\\')) cur[--n] = '\0';
  while (n > 1) {
    size_t sep = n;
    while (sep > 0 && cur[sep - 1] != '/' && cur[sep - 1] != '\\') sep--;
    if (sep == 0) break;
    size_t plen = sep - 1;
    char saved = cur[plen];
    cur[plen] = '\0';
    const char* parent = (plen == 0) ? "/" : cur;
    struct stat ps;
    bool same = (stat(parent, &ps) == 0 && ps.st_dev == dev);
    cur[plen] = saved;
    if (!same) break;
    if (plen == 0) { cur[0] = '/'; cur[1] = '\0'; n = 1; break; }
    n = plen;
    cur[n] = '\0';
  }
  return cur;
}

// as_trash_stamp: the " HH-MM-SS-mmm" collision suffix macOS inserts (measured:
// "x.txt" -> "x.txt 18-34-09-271.txt"). Local time, like Finder.
static void as_trash_stamp(char* out, size_t cap, int attempt) {
  int h, m, s, ms;
#ifdef _WIN32
  SYSTEMTIME lt;
  GetLocalTime(&lt);
  h = lt.wHour; m = lt.wMinute; s = lt.wSecond; ms = (int)lt.wMilliseconds;
#elif defined(__wasi__) || defined(__EMSCRIPTEN__)
  h = 0; m = 0; s = 0; ms = 0;
#else
  struct timeval tv;
  struct tm lt;
  gettimeofday(&tv, NULL);
  localtime_r(&tv.tv_sec, &lt);
  h = lt.tm_hour; m = lt.tm_min; s = lt.tm_sec; ms = (int)(tv.tv_usec / 1000);
#endif
  if (attempt == 0) snprintf(out, cap, " %02d-%02d-%02d-%03d", h, m, s, ms);
  else snprintf(out, cap, " %02d-%02d-%02d-%03d-%d", h, m, s, ms, attempt);
}

// as_trash_target: dir/name, or -- when that name is taken -- the name macOS
// gives the second copy: the item keeps its WHOLE name (extension included), then
// " HH-MM-SS-mmm", then the extension again. Measured on 51.4.1:
// "x.txt" -> "x.txt 18-34-09-271.txt", "dupsub" -> "dupsub 18-37-21-029".
static char* as_trash_target(const char* dir, const char* name) {
  char* plain = as_path_join(dir, name);
  if (!as_path_exists(plain)) return plain;
  const char* dot = NULL;
  for (const char* q = name; *q != '\0'; q++) if (*q == '.') dot = q;
  const char* ext = (dot != NULL && dot != name) ? dot : "";
  size_t nl = strlen(name), el = strlen(ext);
  for (int attempt = 0; attempt < 64; attempt++) {
    char stamp[48];
    as_trash_stamp(stamp, sizeof stamp, attempt);
    size_t sl = strlen(stamp);
    char* stamped = as_str_alloc(nl + sl + el + 1);
    memcpy(stamped, name, nl);
    memcpy(stamped + nl, stamp, sl);
    memcpy(stamped + nl + sl, ext, el);
    stamped[nl + sl + el] = '\0';
    char* target = as_path_join(dir, stamped);
    if (!as_path_exists(target)) return target;
  }
  return NULL;
}

// as_trash_dir: the directory this path is trashed into, or NULL when there is
// no usable trash for it (which the caller turns into #2038).
static char* as_trash_dir(const char* path) {
#if defined(__wasi__) || defined(__EMSCRIPTEN__)
  (void)path;
  return NULL;
#elif defined(_WIN32)
  // Windows never reaches this: as_trash_move routes to as_trash_move_shell
  // first, because the Recycle Bin is not a directory to rename into. The arm
  // exists only so this #if chain stays exhaustive for the target.
  (void)path;
  return NULL;
#elif defined(__APPLE__)
  struct stat st;
  if (path == NULL || stat(path, &st) != 0) return NULL;
  char* home = as_home_dir();
  struct stat hs;
  if (home != NULL && stat(home, &hs) == 0 && hs.st_dev == st.st_dev) {
    char* t = as_path_join(home, ".Trash");
    if (as_path_is_dir(t)) return t;
    as_mkdirs(t);
    return as_path_is_dir(t) ? t : NULL;
  }
  char* root = as_volume_root(path);
  if (root == NULL) return NULL;
  char owner[40];
  snprintf(owner, sizeof owner, ".Trashes/%d", (int)getuid());
  char* t = as_path_join(root, owner);
  if (as_path_is_dir(t)) return t;
  as_mkdirs(t);
  return as_path_is_dir(t) ? t : NULL;
#else
  // freedesktop.org trash: $XDG_DATA_HOME/Trash (default ~/.local/share/Trash)
  // holds the payloads under files/ and a .trashinfo beside each one under
  // info/, so the desktop can restore it. A path on another volume uses
  // <volume root>/.Trash/<uid>, per the specification.
  struct stat st, hs;
  if (path == NULL || stat(path, &st) != 0) return NULL;
  char* home = as_home_dir();
  bool home_volume = (home != NULL && stat(home, &hs) == 0 && hs.st_dev == st.st_dev);
  char* base;
  if (home_volume) {
    const char* xdg = getenv("XDG_DATA_HOME");
    base = (xdg != NULL && xdg[0] == '/') ? as_path_join(xdg, "Trash") : as_path_join(home, ".local/share/Trash");
  } else {
    char* root = as_volume_root(path);
    if (root == NULL) return NULL;
    char owner[40];
    snprintf(owner, sizeof owner, ".Trash/%d", (int)getuid());
    base = as_path_join(root, owner);
  }
  char* files = as_path_join(base, "files");
  if (!as_path_is_dir(files)) as_mkdirs(files);
  return as_path_is_dir(files) ? files : NULL;
#endif
}

// as_trash_note: record where the payload came from, for the desktop's "put
// back". Only the freedesktop layout has such a sidecar; Finder (macOS) does
// not (it stores the Put Back location in the volume's metadata).
static void as_trash_note(const char* files_dir, const char* moved_path, const char* original) {
#if !defined(__APPLE__) && !defined(_WIN32) && !defined(__wasi__) && !defined(__EMSCRIPTEN__)
  size_t fl = strlen(files_dir);
  if (fl <= 5 || strcmp(files_dir + fl - 5, "files") != 0) return;
  char* base = as_str_alloc(fl - 4);
  memcpy(base, files_dir, fl - 5);
  base[fl - 5] = '\0';
  char* info = as_path_join(base, "info");
  if (!as_path_is_dir(info)) as_mkdirs(info);
  if (!as_path_is_dir(info)) return;
  char* leaf = as_path_basename(moved_path);
  if (leaf == NULL) return;
  char* leafinfo = as_str_concat(leaf, ".trashinfo");
  char* note = as_path_join(info, leafinfo);
  FILE* fp = fopen(note, "w");
  if (fp == NULL) return;
  fprintf(fp, "[Trash Info]\nPath=");
  for (const char* q = original; *q != '\0'; q++) {
    unsigned char c = (unsigned char)*q;
    bool keep = ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ||
                 c == '/' || c == '.' || c == '_' || c == '-');
    if (keep) fputc((int)c, fp);
    else fprintf(fp, "%%%02X", (unsigned)c);
  }
  time_t now = time(NULL);
  struct tm lt;
  localtime_r(&now, &lt);
  fprintf(fp, "\nDeletionDate=%04d-%02d-%02dT%02d:%02d:%02d\n", lt.tm_year + 1900, lt.tm_mon + 1, lt.tm_mday, lt.tm_hour, lt.tm_min, lt.tm_sec);
  fclose(fp);
#else
  (void)files_dir; (void)moved_path; (void)original;
#endif
}

// as_trash_move_shell: the Windows arm -- hand the path to the shell-owned
// Recycle Bin operation. FOF_ALLOWUNDO is what makes the item RECOVERABLE instead
// of erased, and the absence of any confirmation UI keeps the call as silent as
// AIR is. A volume with no Recycle Bin at all (a removable drive, or a bin the
// user turned off) makes the shell delete the item, which is precisely what the
// AS3 reference prescribes for such a host ("on operating systems that do not
// support the concept of a recoverable trash folder, the files are removed
// immediately") -- the shell answering, not a fallback invented here.
//
// The wide conversion is CP_ACP, not CP_UTF8, because every other Windows path
// call in this runtime is the ANSI one (stat, GetModuleFileNameA, remove): that
// is the same reading of the same bytes, whereas decoding as UTF-8 would send
// the shell to a path the rest of the runtime cannot see.
//
// The caller has already rejected NULL/empty (2037) and a path that does not
// exist (3003) -- measured: adl answers those with the same two numbers on
// Windows as it does on macOS, so the shared prelude is not skipped here.
#ifdef _WIN32
static long as_trash_move_shell(const char* path) {
  // SHFileOperationW takes a DOUBLE-NUL-terminated list of paths, so `from`
  // carries one terminator past the end of the string.
  int need = MultiByteToWideChar(CP_ACP, 0, path, -1, NULL, 0);
  if (need <= 0) return 2038;
  WCHAR* from = (WCHAR*)as_alloc((size_t)(need + 1) * sizeof(WCHAR));
  if (MultiByteToWideChar(CP_ACP, 0, path, -1, from, need) <= 0) return 2038;
  from[need] = 0;
  SHFILEOPSTRUCTW op;
  memset(&op, 0, sizeof op);
  op.wFunc = FO_DELETE;
  op.pFrom = from;
  op.fFlags = FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_NOERRORUI | FOF_SILENT;
  if (SHFileOperationW(&op) != 0) return 2038;
  if (op.fAnyOperationsAborted) return 2038;
  return 0;
}
#endif

// as_trash_move: 0 on success, else the AIR error number to report.
static long as_trash_move(const char* path) {
  if (path == NULL || path[0] == '\0') return 2037;
  struct stat st;
  if (stat(path, &st) != 0) return 3003;
#ifdef _WIN32
  return as_trash_move_shell(path);
#else
  char* dir = as_trash_dir(path);
  if (dir == NULL) return 2038;
  char* name = as_path_basename(path);
  if (name == NULL) return 2038;
  // Already inside the trash directory: AIR treats this as a successful no-op.
  size_t dl = strlen(dir);
  if (strncmp(path, dir, dl) == 0 && path[dl] == '/') {
    bool nested = false;
    for (const char* q = path + dl + 1; *q != '\0'; q++) if (*q == '/') nested = true;
    if (!nested) return 0;
  }
  char* target = as_trash_target(dir, name);
  if (target == NULL) return 2038;
  if (rename(path, target) != 0) return 2038;
  as_trash_note(dir, target, path);
  return 0;
#endif
}

static void File_moveToTrash(void* _this) {
  long err = as_trash_move(((File*)_this)->nativePath);
  if (err == 0) return;
  if (err == 2037) { as_throw(Error_new((char*)"Error #2037: Functions called in incorrect sequence, or earlier call was unsuccessful.", 2037)); return; }
  if (err == 3003) { as_throw(Error_new((char*)"Error #3003: File or directory does not exist.", 3003)); return; }
  as_throw(IOError_new((char*)"Error #2038: File I/O Error.", 2038));
}
// moveToTrashAsync dispatches its outcome instead of throwing (measured: a
// missing path is an ioError, not an exception). AIR delivers the event from
// its own IO thread; this build performs the move inline and dispatches from
// the same call -- the convention every other async member of File follows
// here (see File_getDirectoryListingAsync).
static void File_moveToTrashAsync(void* _this) {
  File* o = (File*)_this;
  long err = as_trash_move(o->nativePath);
  if (err == 2037) { as_throw(Error_new((char*)"Error #2037: Functions called in incorrect sequence, or earlier call was unsuccessful.", 2037)); return; }
  if (err == 0) { EventDispatcher_dispatchEvent((void*)o, Event_new((char*)"complete", false, false)); return; }
  const char* text = (err == 3003) ? "Error #3003: File or directory does not exist." : "Error #2038: File I/O Error.";
  IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, (char*)text);
  ev->errorID = (int)err;
  EventDispatcher_dispatchEvent((void*)o, (Event*)ev);
}
static void File_moveTo(void* _this, File* target, bool overwrite, bool force) {
  File* o = (File*)_this;
  if (target == NULL || o->nativePath == NULL || target->nativePath == NULL) return;
  if (!as_path_exists(o->nativePath)) { as_shell_unsupported("File.moveTo with a source path that does not exist (AIR throws IOError)"); return; }
  if (as_path_exists(target->nativePath) && !(overwrite || force)) { as_shell_unsupported("File.moveTo onto an existing path with overwrite/force false (AIR throws IOError)"); return; }
  if (rename(o->nativePath, target->nativePath) != 0) { as_shell_unsupported("File.moveTo across volumes (rename failed)"); return; }
  o->nativePath = target->nativePath;
  gc_write_barrier((void*)o->nativePath);
}
static void File_getDirectoryListingAsync(void* _this) {
  File* o = (File*)_this;
  EventDispatcher_dispatchEvent((void*)o, (Event*)FileListEvent_new((char*)"directoryListing", false, false, o, File_getDirectoryListing(_this)));
}
static void File_deleteFileAsync(void* _this) {
  File_deleteFile(_this);
  EventDispatcher_dispatchEvent((void*)_this, Event_new((char*)"complete", false, false));
}
static void File_cancel(void* _this) { (void)_this; }
static void File_deleteDirectoryAsync(void* _this, bool deleteDirectory) {
  (void)deleteDirectory;
  File_deleteDirectory(_this);
  EventDispatcher_dispatchEvent((void*)_this, Event_new((char*)"complete", false, false));
}
static void File_browseForDirectory(void* _this, char* title) { (void)_this; (void)title; as_shell_unsupported((char*)"flash.filesystem.File.browseForDirectory"); }
static void File_browseForOpen(void* _this, char* title, as_array* typeFilter) { (void)_this; (void)title; (void)typeFilter; as_shell_unsupported((char*)"flash.filesystem.File.browseForOpen"); }
static void File_openWithDefaultApplication(void* _this) { (void)_this; as_shell_unsupported((char*)"flash.filesystem.File.openWithDefaultApplication"); }
static void File_upload(void* _this, URLRequest* request, char* uploadDataFieldName, bool testUpload) { (void)_this; (void)request; (void)uploadDataFieldName; (void)testUpload; as_shell_unsupported((char*)"flash.filesystem.File.upload (no HTTP upload backend in this build)"); }
static as_array* File_getDirectoryListing(void* _this) {
  File* o = (File*)_this;
  as_array* result = as_array_new();
  if (o->nativePath == NULL) return result;
  #ifdef _WIN32
  // MSVC has no dirent.h; enumerate with FindFirstFile/FindNextFile, which
  // want a backslash separator (FindFirstFile rejects the '/' as_path_join
  // produces), so build a "<dir>\*" pattern and swap separators as we copy.
  {
    size_t n = strlen(o->nativePath);
    char* pat = (char*)malloc(n + 3);
    size_t i;
    memcpy(pat, o->nativePath, n);
    for (i = 0; i < n; i++) if (pat[i] == '/') pat[i] = '\\';
    pat[n] = '\\'; pat[n + 1] = '*'; pat[n + 2] = '\0';
    WIN32_FIND_DATAA fd;
    HANDLE h = FindFirstFileA(pat, &fd);
    free(pat);
    if (h == INVALID_HANDLE_VALUE) return result;
    do {
      if (strcmp(fd.cFileName, ".") == 0 || strcmp(fd.cFileName, "..") == 0) continue;
      as_array_push(result, as_v_obj((void*)File_new(as_path_join(o->nativePath, fd.cFileName))));
    } while (FindNextFileA(h, &fd) != 0);
    FindClose(h);
  }
  #else
  DIR* d = opendir(o->nativePath);
  if (d == NULL) return result;
  struct dirent* e;
  while ((e = readdir(d)) != NULL) {
    if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
    as_array_push(result, as_v_obj((void*)File_new(as_path_join(o->nativePath, e->d_name))));
  }
  closedir(d);
  #endif
  return result;
}

static void FileStream_ctor(FileStream* o) { EventDispatcher_ctor((EventDispatcher*)o, NULL); o->_handle = NULL; }
static FileStream* FileStream_new(void) { FileStream* o = (FileStream*)gc_alloc(GCT_CLASS, sizeof(FileStream)); o->vtable = &FileStream_vt; FileStream_ctor(o); return o; }
static void FileStream_open(void* _this, File* file, char* fileMode) {
  FileStream* o = (FileStream*)_this;
  if (o->_handle != NULL) { fclose((FILE*)o->_handle); o->_handle = NULL; }
  if (file == NULL || file->nativePath == NULL) return;
  const char* mode = "rb";
  if (fileMode != NULL) {
    if (strcmp(fileMode, "write") == 0) mode = "wb";
    else if (strcmp(fileMode, "append") == 0) mode = "ab";
    else if (strcmp(fileMode, "update") == 0) mode = "r+b";
  }
  o->_handle = (void*)fopen(file->nativePath, mode);
  if (o->_handle != NULL) setvbuf((FILE*)o->_handle, NULL, _IONBF, 0);
}
static void FileStream__openFinish(void* job) {
  FileStream* o = (FileStream*)as_job_obj(job);
  if (as_job_failed(job)) { EventDispatcher_dispatchEvent((void*)o, (Event*)IOErrorEvent_new((char*)"ioError", false, false, (char*)"FileStream open failed")); return; }
  unsigned total = as_job_total(job);
  o->_handle = as_job_take_handle(job);
  EventDispatcher_dispatchEvent((void*)o, (Event*)ProgressEvent_new((char*)"progress", false, false, total, total));
  EventDispatcher_dispatchEvent((void*)o, (Event*)Event_new((char*)"complete", false, false));
}
static void FileStream_openAsync(void* _this, File* file, char* fileMode) {
  FileStream* o = (FileStream*)_this;
  if (o->_handle != NULL) { fclose((FILE*)o->_handle); o->_handle = NULL; }
  as_async_submit(AS_JOB_FS_OPEN, (void*)o, FileStream__openFinish, (file != NULL) ? file->nativePath : NULL, fileMode, 0);
}
static void FileStream_close(void* _this) { FileStream* o = (FileStream*)_this; if (o->_handle != NULL) { fclose((FILE*)o->_handle); o->_handle = NULL; } }
static char* FileStream_readUTFBytes(void* _this, unsigned length) {
  FileStream* o = (FileStream*)_this;
  FILE* f = (FILE*)o->_handle;
  if (f == NULL) return NULL;
  char* buf = as_str_alloc((size_t)length + 1);
  size_t n = fread(buf, 1, (size_t)length, f);
  buf[n] = '\0';
  return buf;
}
static void FileStream_writeUTFBytes(void* _this, char* value) {
  FileStream* o = (FileStream*)_this;
  FILE* f = (FILE*)o->_handle;
  if (f != NULL && value != NULL) fwrite(value, 1, strlen(value), f);
}
static unsigned FileStream_get_position(void* _this) { FileStream* o = (FileStream*)_this; FILE* f = (FILE*)o->_handle; return (f == NULL) ? 0u : (unsigned)ftell(f); }
static unsigned FileStream_get_bytesAvailable(void* _this) {
  FileStream* o = (FileStream*)_this;
  FILE* f = (FILE*)o->_handle;
  if (f == NULL) return 0u;
  long cur = ftell(f);
  fseek(f, 0, SEEK_END);
  long end = ftell(f);
  fseek(f, cur, SEEK_SET);
  return (unsigned)(end - cur);
}
static void FileStream_readBytes(void* _this, ByteArray* bytes, unsigned offset, unsigned length) {
  FileStream* o = (FileStream*)_this;
  FILE* f = (FILE*)o->_handle;
  if (f == NULL || bytes == NULL) return;
  if (length == 0) {
    long cur = ftell(f); fseek(f, 0, SEEK_END); long end = ftell(f); fseek(f, cur, SEEK_SET);
    length = (unsigned)(end - cur);
  }
  as_ba_grow(bytes, (int)(offset + length));
  size_t n = fread((unsigned char*)bytes->data + offset, 1, (size_t)length, f);
  if ((int)(offset + n) > bytes->length) bytes->length = (int)(offset + n);
}
static void FileStream_writeBytes(void* _this, ByteArray* bytes, unsigned offset, unsigned length) {
  FileStream* o = (FileStream*)_this;
  FILE* f = (FILE*)o->_handle;
  if (f == NULL || bytes == NULL) return;
  if (length == 0) length = (unsigned)(bytes->length - (int)offset);
  if ((int)(offset + length) > bytes->length) length = (unsigned)(bytes->length - (int)offset);
  if (length > 0) fwrite((unsigned char*)bytes->data + offset, 1, (size_t)length, f);
}

static unsigned int ASC_so_default_encoding = 3u;
static bool ASC_so_prevent_backup = false;
static void as_so_mkparent(const char* p) {
  if (p == NULL) return;
  const char* slash = NULL;
  for (const char* s = p; *s != '\0'; s++) if (*s == '/') slash = s;
  if (slash == NULL || slash == p) return;
  size_t n = (size_t)(slash - p);
  char* dir = as_alloc(n + 1);
  memcpy(dir, p, n); dir[n] = '\0';
  as_mkdirs(dir);
}
static void as_so_reject(void) { as_throw(Error_new((char*)"Error #2134: Cannot create SharedObject.", 2134)); }
static bool as_so_name_bad(int c) {
  if (c <= 0x20) return true;  // space plus every C0 control, TAB/LF/CR included
  return c != 0 && strchr("\"#&',:;<>?\\~", c) != NULL;
}
static void as_so_check_name(const char* name) {
  if (name[0] == '\0') as_so_reject();  // an empty name is #2134, not #2007
  for (const char* s = name; *s != '\0'; s++) if (as_so_name_bad((unsigned char)*s)) as_so_reject();
  const char* n = name;
  if (n[0] == '/') n++;
  if (n[0] == '.' && n[1] == '/') n += 2;
  for (const char* c = n; ; ) {
    const char* e = strchr(c, '/');
    if (e == NULL) break;  // the last component may be empty ("trail/")
    if (e == c) as_so_reject();  // empty component
    if (c == n && e == c + 2 && c[0] == '.' && c[1] == '.') as_so_reject();  // escapes the layer
    c = e + 1;
  }
}
static char* as_so_layer(const char* localPath) {
  if (localPath == NULL) return (char*)ASC_SWF_PATH;
  if (localPath[0] == '\0') as_so_reject();  // "" is not null (SoD p7)
  const char* s = localPath;
  if (s[0] == '/') s++;
  size_t len = strlen(s);
  if (len > 0 && s[len - 1] == '/') len--;
  const char* c = ASC_SWF_PATH;
  for (size_t i = 0; i < len; ) {
    size_t j = i;
    while (j < len && s[j] != '/') j++;
    if (j == i) as_so_reject();  // empty component ("//x", "x//y")
    if (ASC_SWF_PATH[0] != '\0') {
      size_t k = 0;
      while (k < j - i && c[k] != '\0' && c[k] != '/') k++;
      if (k != j - i || memcmp(s + i, c, k) != 0) as_so_reject();  // not a prefix of <content>
      c += (c[k] == '/') ? k + 1 : k;
    }
    i = j + 1;
  }
  char* out = as_alloc(len + 1);
  memcpy(out, s, len);
  out[len] = '\0';
  return out;
}
static char* as_so_file_name(const char* name) {
  const char* n = name;
  if (n[0] == '/') n++;
  if (n[0] == '.' && n[1] == '/') n += 2;
  if (strchr(n, '/') != NULL) return as_str_concat(as_str_concat((char*)"#", (char*)n), (char*)".sol");
  return as_str_concat((char*)n, (char*)".sol");
}
static char* as_so_path(const char* name, const char* localPath) {
  char* base = as_app_storage_dir();
  base = as_path_join(base, "#SharedObjects");
  char* layer = as_so_layer(localPath);
  if (layer[0] != '\0') base = as_path_join(base, layer);
  return as_path_join(base, as_so_file_name(name == NULL ? (char*)"" : name));
}
static unsigned char* as_so_load_bytes(const char* p, size_t* out_len) {
  *out_len = 0;
  FILE* f = fopen(p, "rb");
  if (f == NULL) return NULL;
  size_t cap = 4096, len = 0, n = 0;
  unsigned char* buf = (unsigned char*)as_alloc(cap);
  while ((n = fread(buf + len, 1, cap - len, f)) > 0) {
    len += n;
    if (len == cap) { unsigned char* nb = (unsigned char*)as_alloc(cap * 2); memcpy(nb, buf, len); buf = nb; cap *= 2; }
  }
  fclose(f);
  *out_len = len;
  return buf;
}
static void as_so_read_entries(SharedObject* o, const unsigned char* buf, size_t len) {
  if (len < 24 || buf[0] != 0x00 || buf[1] != 0xBF || memcmp(buf + 6, "TCSO", 4) != 0) return;
  unsigned nameLen = (unsigned)((buf[16] << 8) | buf[17]);
  size_t pos = 18 + (size_t)nameLen + 4;
  if (pos >= len) return;
  as_amf3r r;
  memset(&r, 0, sizeof(r));
  r.p = buf;
  r.len = len;
  r.pos = pos;
  while (r.pos < r.len && r.code == 0) {
    char* key = as_amfr_str_body(&r);
    if (r.code != 0) break;
    as_value v = as_amf3_rvalue(&r);
    as_dyn_set((void*)o->_data, key, v);
    if (!as_amfr_have(&r, 1)) break;
    r.pos += 1;  // per-entry 0x00 terminator
  }
  for (int i = 0; i < r.ntr; i++) free(r.traits[i].members);
  free(r.traits); free(r.strs); free(r.objs);
}
static void SharedObject_ctor(SharedObject* o) {
  EventDispatcher_ctor((EventDispatcher*)o, NULL);
  o->name = NULL;
  o->path = NULL;
  o->_data = as_object_new();
  o->_client = (void*)o;
  o->_objectEncoding = ASC_so_default_encoding;
  o->_fps = 0.0;
}
static SharedObject* SharedObject_new(void) { SharedObject* o = (SharedObject*)gc_alloc(GCT_CLASS, sizeof(SharedObject)); o->vtable = &SharedObject_vt; SharedObject_ctor(o); return o; }
static SharedObject* as_so_make(char* name, char* path) {
  SharedObject* o = (SharedObject*)gc_alloc(GCT_CLASS, sizeof(SharedObject));
  o->vtable = &SharedObject_vt;
  SharedObject_ctor(o);
  o->name = name; gc_write_barrier((void*)name);
  o->path = path; gc_write_barrier((void*)path);
  size_t len = 0;
  unsigned char* buf = as_so_load_bytes(path, &len);
  if (buf != NULL) as_so_read_entries(o, buf, len);
  return o;
}
static unsigned char* as_so_serialize(SharedObject* o, size_t* out_len) {
  as_amf3w w;
  memset(&w, 0, sizeof(w));
  size_t nameLen = o->name == NULL ? 0 : strlen(o->name);
  as_amfb_byte(&w.out, 0x00);
  as_amfb_byte(&w.out, 0xBF);
  as_amfb_bytes_be32(&w.out, 0);  // patched below: fileSize - 6
  as_amfb_bytes(&w.out, (const unsigned char*)"TCSO", 4);
  as_amfb_byte(&w.out, 0x00);
  as_amfb_byte(&w.out, 0x04);
  as_amfb_bytes_be32(&w.out, 0);
  as_amfb_byte(&w.out, (unsigned)((nameLen >> 8) & 0xFFu));
  as_amfb_byte(&w.out, (unsigned)(nameLen & 0xFFu));
  if (nameLen > 0) as_amfb_bytes(&w.out, (const unsigned char*)o->name, nameLen);
  as_amfb_byte(&w.out, 0x00);
  as_amfb_byte(&w.out, 0x00);
  as_amfb_byte(&w.out, 0x00);
  as_amfb_byte(&w.out, 0x03);
  for (int i = 0; i < o->_data->length; i++) {
    char* key = o->_data->keys[i];
    as_amf3_wstr_body(&w, key);  // U29S; a repeated key text becomes a reference
    as_amf3_wvalue(&w, o->_data->vals[i]);
    as_amfb_byte(&w.out, 0x00);
  }
  unsigned payload = (unsigned)(w.out.len - 6);
  w.out.b[2] = (unsigned char)((payload >> 24) & 0xFFu);
  w.out.b[3] = (unsigned char)((payload >> 16) & 0xFFu);
  w.out.b[4] = (unsigned char)((payload >> 8) & 0xFFu);
  w.out.b[5] = (unsigned char)(payload & 0xFFu);
  free(w.strs); free(w.objs); free(w.traits);
  *out_len = w.out.len;
  return w.out.b;
}
static int as_so_flush(SharedObject* o);
static void as_so_flush_all(void) {
  if (SharedObject__cache == NULL) return;
  for (int i = 0; i < SharedObject__cache->length; i++) {
    SharedObject* c = (SharedObject*)as_v_obj_val(SharedObject__cache->data[i]);
    if (c == NULL || c->path == NULL || c->_data == NULL || c->_data->length == 0) continue;
    as_so_flush(c);
  }
}
static SharedObject* SharedObject_getLocal_static(char* name, char* localPath, bool secure) {
  (void)secure;  // this subset has no encrypted local store
  if (name == NULL) { as_throw(Error_new((char*)"Error #2007: Parameter name must be non-null.", 2007)); return NULL; }
  as_so_check_name(name);  // #2134: empty name, a rejected character, an escaping shape
  char* path = as_so_path(name, localPath);
  if (SharedObject__cache == NULL) { SharedObject__cache = as_array_new(); atexit(as_so_flush_all); }
  for (int i = 0; i < SharedObject__cache->length; i++) {
    SharedObject* c = (SharedObject*)as_v_obj_val(SharedObject__cache->data[i]);
    if (c != NULL && c->path != NULL && strcmp(c->path, path) == 0) return c;
  }
  SharedObject* so = as_so_make(name, path);
  as_array_push(SharedObject__cache, as_v_obj((void*)so));
  return so;
}
static Object* SharedObject_get_data(void* _this) { SharedObject* o = (SharedObject*)_this; return (Object*)o->_data; }
static unsigned int SharedObject_get_size(void* _this) {
  SharedObject* o = (SharedObject*)_this;
  if (o->_data->length == 0) return 0;
  size_t len = 0;
  unsigned char* buf = as_so_serialize(o, &len);
  free(buf);
  return (unsigned int)len;
}
static Object* SharedObject_get_client(void* _this) { return (Object*)((SharedObject*)_this)->_client; }
static void SharedObject_set_client(void* _this, Object* value) { SharedObject* o = (SharedObject*)_this; o->_client = (void*)value; gc_write_barrier((void*)value); }
static unsigned int SharedObject_get_objectEncoding(void* _this) { return ((SharedObject*)_this)->_objectEncoding; }
static void SharedObject_set_objectEncoding(void* _this, unsigned int value) { ((SharedObject*)_this)->_objectEncoding = value; }
static void SharedObject_set_fps(void* _this, double value) { ((SharedObject*)_this)->_fps = value; }
static unsigned int SharedObject_get_defaultObjectEncoding_static(void* _this) { (void)_this; return ASC_so_default_encoding; }
static void SharedObject_set_defaultObjectEncoding_static(void* _this, unsigned int value) { (void)_this; ASC_so_default_encoding = value; }
static bool SharedObject_get_preventBackup_static(void* _this) { (void)_this; return ASC_so_prevent_backup; }
static void SharedObject_set_preventBackup_static(void* _this, bool value) { (void)_this; ASC_so_prevent_backup = value; }
static int as_so_flush(SharedObject* o) {
  if (o->path == NULL) return 1;
  as_so_mkparent(o->path);
  size_t len = 0;
  unsigned char* buf = as_so_serialize(o, &len);
  FILE* f = fopen(o->path, "wb");
  if (f == NULL) { free(buf); return 0; }
  if (len > 0) fwrite(buf, 1, len, f);
  fclose(f);
  free(buf);
  return 1;
}
static char* SharedObject_flush(void* _this, int minDiskSpace) {
  (void)minDiskSpace;
  if (!as_so_flush((SharedObject*)_this)) { as_throw(Error_new((char*)"SharedObject.flush: cannot write the storage file", 0)); return (char*)"pending"; }
  return (char*)"flushed";
}
static void SharedObject_clear(void* _this) {
  SharedObject* o = (SharedObject*)_this;
  o->_data = as_object_new();
  gc_write_barrier((void*)o->_data);
  if (o->path != NULL) remove(o->path);
}
static void SharedObject_close(void* _this) { (void)_this; }
static void SharedObject_setDirty(void* _this, char* propertyName) { (void)_this; (void)propertyName; }
static void SharedObject_setProperty(void* _this, char* propertyName, as_value value) {
  SharedObject* o = (SharedObject*)_this;
  if (propertyName == NULL) return;
  as_object_set(o->_data, propertyName, value);
}
static SharedObject* SharedObject_getRemote_static(char* name, char* remotePath, as_value persistence, bool secure) {
  (void)name; (void)remotePath; (void)persistence; (void)secure;
  as_throw(Error_new((char*)"SharedObject.getRemote requires a Flash Media Server connection, which this AOT runtime does not provide (only local shared objects are supported)", 0));
  return NULL;
}
static void SharedObject_connect(void* _this, as_value myConnection, as_value params) { (void)_this; (void)myConnection; (void)params; as_throw(Error_new((char*)"SharedObject.connect requires a Flash Media Server connection, which this AOT runtime does not provide", 0)); }
static void SharedObject_send(void* _this, as_array* arguments) { (void)_this; (void)arguments; as_throw(Error_new((char*)"SharedObject.send requires a Flash Media Server connection, which this AOT runtime does not provide", 0)); }

static int as_graphics_bound(DisplayObject* o, double* l, double* t, double* r, double* b);
static Graphics* as_graphics_of(DisplayObject* o);
static int as_graphics_empty(Graphics* g);
static void as_graphics_paint(void* canvas, Graphics* g);
static void as_swc_bind(DisplayObject* o, int charId);
static void as_swc_tl_start(MovieClip* o, int charId);
static int as_bounds_walk(DisplayObject* o, int with_stroke, int decl, double* l, double* t, double* r, double* b);
static void as_do_point(DisplayObject* o, double* x, double* y);
static void as_do_matrix(DisplayObject* o, double* a, double* b, double* c, double* d, double* tx, double* ty);
static void as_mat_mul(double a1, double b1, double c1, double d1, double tx1, double ty1, double a2, double b2, double c2, double d2, double tx2, double ty2, double* a, double* b, double* c, double* d, double* tx, double* ty);
static int as_mat_invert(double a, double b, double c, double d, double tx, double ty, double* ra, double* rb, double* rc, double* rd, double* rtx, double* rty);
static int as_local_point(DisplayObject* o, double gx, double gy, double* lx, double* ly);
static void as_to_stage_matrix(DisplayObject* o, double* a, double* b, double* c, double* d, double* tx, double* ty);
static void as_rect_xform(double* l, double* t, double* r, double* b, double ma, double mb, double mc, double md, double mtx, double mty);
static void as_rect_to_stage(DisplayObject* o, double* l, double* t, double* r, double* b);
static void as_rect_from_stage(DisplayObject* o, double* l, double* t, double* r, double* b);
