static void as_blur_apply(unsigned* dst, const unsigned* src, int w, int h, int rx, int ry, int passes) {
  if (w <= 0 || h <= 0) return;
  unsigned* tmp = (unsigned*)malloc(sizeof(unsigned) * (size_t)(w * h));
  unsigned* a = (unsigned*)malloc(sizeof(unsigned) * (size_t)(w * h));
  memcpy(a, src, sizeof(unsigned) * (size_t)(w * h));
  if (rx < 0) rx = 0; if (ry < 0) ry = 0; if (passes < 1) passes = 1;
  for (int p = 0; p < passes; p++) {
    for (int y = 0; y < h; y++) {
      const unsigned* row = a + (size_t)y * w; unsigned* out = tmp + (size_t)y * w;
      for (int x = 0; x < w; x++) {
        int lo = x - rx; if (lo < 0) lo = 0; int hi = x + rx; if (hi >= w) hi = w - 1;
        long sa = 0, sr = 0, sg = 0, sb = 0; int cnt = 0;
        for (int xx = lo; xx <= hi; xx++) { unsigned c = row[xx]; sa += c >> 24; sr += (c >> 16) & 0xFF; sg += (c >> 8) & 0xFF; sb += c & 0xFF; cnt++; }
        out[x] = (unsigned)((sa / cnt) << 24) | (unsigned)((sr / cnt) << 16) | (unsigned)((sg / cnt) << 8) | (unsigned)(sb / cnt);
      }
    }
    for (int x = 0; x < w; x++) {
      for (int y = 0; y < h; y++) {
        int lo = y - ry; if (lo < 0) lo = 0; int hi = y + ry; if (hi >= h) hi = h - 1;
        long sa = 0, sr = 0, sg = 0, sb = 0; int cnt = 0;
        for (int yy = lo; yy <= hi; yy++) { unsigned c = tmp[(size_t)yy * w + x]; sa += c >> 24; sr += (c >> 16) & 0xFF; sg += (c >> 8) & 0xFF; sb += c & 0xFF; cnt++; }
        a[(size_t)y * w + x] = (unsigned)((sa / cnt) << 24) | (unsigned)((sr / cnt) << 16) | (unsigned)((sg / cnt) << 8) | (unsigned)(sb / cnt);
      }
    }
  }
  memcpy(dst, a, sizeof(unsigned) * (size_t)(w * h));
  free(tmp); free(a);
}
