  as_tf_scroll_caret(tf, as_tf_line_of_index(starts, n, caret), 0);
  int maxsh = TextField_get_maxScrollH((void*)tf);
  if (maxsh <= 0) { tf->_scroll_h = 0; return; }
  void* para = as_tf_paragraph(tf);
  if (para == NULL) return;
  double cx = 0.0, cy = 0.0, ch = 0.0;
  if (!as_skia_textlayout_caret_rect(para, as_tf_utf16_index(tf, caret), &cx, &cy, &ch)) return;
