static const uint32_t* as_tex_argb_from_byte_array(ByteArray* data, unsigned int off, int w, int h, char* format, int* out_swizzled) {
  int n = w * h;
  if (n < 0) n = 0;
  if (out_swizzled != NULL) *out_swizzled = 0;
  if (data == NULL) { as_throw(TypeError_new((char*)"Error #2007: Parameter data must be non-null.", 2007)); return NULL; }
  if (format == NULL || (strcmp(format, "bgra") != 0 && strcmp(format, "rgba") != 0)) {
    as_shell_unsupported("Texture.uploadFromByteArray (non-8-bit texture format)");
    return NULL;
  }
  if ((size_t)off >= (size_t)data->length || (size_t)data->length - (size_t)off < (size_t)n * 4) {
    as_throw(RangeError_new((char*)"Error #2004: One of the parameters is invalid.", 2004));
    return NULL;
  }
  const uint32_t* src = (const uint32_t*)((const unsigned char*)data->data + off);
  if (strcmp(format, "bgra") == 0) return src;
  uint32_t* out = (uint32_t*)malloc(sizeof(uint32_t) * (size_t)n);
  if (out == NULL) return NULL;
  for (int i = 0; i < n; i++) { uint32_t v = src[i]; out[i] = (v & 0xFF00FF00u) | ((v & 0x00FF0000u) >> 16) | ((v & 0x000000FFu) << 16); }
  if (out_swizzled != NULL) *out_swizzled = 1;
  return out;
}
static void Texture_uploadFromBitmapData(void* _this, BitmapData* bitmapData, unsigned int miplevel) {
  Texture* o = (Texture*)_this;
  if (miplevel != 0) {
    if (o->gpu == NULL || bitmapData == NULL || bitmapData->pixels == NULL) return;
    int nlv = 1, dim = (o->width > o->height) ? o->width : o->height;
    while (dim > 1) { dim >>= 1; nlv++; }
    if ((int)miplevel >= nlv) return;
    int lw = o->width >> miplevel; if (lw < 1) lw = 1;
    int lh = o->height >> miplevel; if (lh < 1) lh = 1;
    if (lw > bitmapData->width) lw = bitmapData->width;
    if (lh > bitmapData->height) lh = bitmapData->height;
    if (lw < 1 || lh < 1) return;
    o->mips = 1;
    as_s3d_texture_upload_level(o->ctx, o->gpu, (int)miplevel, lw, lh, (const uint32_t*)bitmapData->pixels, bitmapData->width);
    return;
  }
  o->mips = 0;
  if (o->gpu != NULL) { as_s3d_destroy_texture(o->gpu); o->gpu = NULL; }
  o->bitmapData = bitmapData; gc_write_barrier((void*)bitmapData);
  if (bitmapData != NULL) { o->width = bitmapData->width; o->height = bitmapData->height; }
  if (o->ctx != NULL && bitmapData != NULL && bitmapData->pixels != NULL) o->gpu = as_s3d_texture_from_pixels(o->ctx, o->width, o->height, (const uint32_t*)bitmapData->pixels);
}
static void Texture_dispose(void* _this) { Texture* o = (Texture*)_this; o->width = 0; o->height = 0; o->format = NULL; o->bitmapData = NULL; as_s3d_destroy_texture(o->gpu); o->gpu = NULL; o->ctx = NULL; }
static void Texture_uploadFromByteArray(void* _this, ByteArray* data, unsigned int byteArrayOffset, unsigned int miplevel) {
  Texture* o = (Texture*)_this;
  if (miplevel != 0) { as_shell_unsupported("Texture.uploadFromByteArray (mip level > 0)"); return; }
  int sw = 0;
  const uint32_t* px = as_tex_argb_from_byte_array(data, byteArrayOffset, o->width, o->height, o->format, &sw);
  if (px == NULL) return;
  if (o->gpu != NULL) { as_s3d_destroy_texture(o->gpu); o->gpu = NULL; }
  o->mips = 0;
  o->bitmapData = NULL;
  if (o->ctx != NULL) o->gpu = as_s3d_texture_from_pixels(o->ctx, o->width, o->height, px);
  if (sw) free((void*)px);
}
