static void Texture_uploadCompressedTextureFromByteArray(void* _this, ByteArray* data, unsigned int byteArrayOffset, bool async) {
  Texture* o = (Texture*)_this;
  int aw = 0, ah = 0;
  unsigned* px = NULL;
  if (data != NULL && data->data != NULL && (size_t)byteArrayOffset < (size_t)data->length)
    px = as_atf_decode_dxt((const unsigned char*)data->data + byteArrayOffset, (int)((size_t)data->length - byteArrayOffset), &aw, &ah);
  if (px != NULL) {
    BitmapData* bd = BitmapData_new(aw, ah, true, 0);
    if (bd != NULL && bd->pixels != NULL) {
      memcpy(bd->pixels, px, sizeof(unsigned) * (size_t)aw * (size_t)ah);
      if (o->gpu != NULL) { as_s3d_destroy_texture(o->gpu); o->gpu = NULL; }
      o->bitmapData = bd; gc_write_barrier((void*)bd);
      o->width = aw; o->height = ah;
      if (o->ctx != NULL) o->gpu = as_s3d_texture_from_pixels(o->ctx, aw, ah, (const uint32_t*)bd->pixels);
    }
    free(px);
  } else {
    as_throw(ArgumentError_new((char*)"Error #3680: ATF data is not in a supported format (only raw DXT containers are decoded)", 0));
  }
  if (async) as_set_timeout(as_fn_make(Texture__textureReady, _this, 0), 0.0);
}
