static bool as_tex_is_pow2(int n) { return n > 0 && (n & (n - 1)) == 0; }
static int as_tex_ceiling(void) { return as_s3d_max_texture_size() >= 4096 ? 4096 : 2048; }
static void as_tex_alloc_failed(void) {
  as_throw(Error_new((char*)"Error #3684: Texture creation failed. Internal error.", 3684));
}
static void as_tex_check_2d(Context3D* ctx, int w, int h) {
  if (w <= 0 || h <= 0)
    as_throw(ArgumentError_new((char*)"Error #3681: Texture size is zero.", 3681));
  if (!as_tex_is_pow2(w) || !as_tex_is_pow2(h))
    as_throw(ArgumentError_new((char*)"Error #3682: Texture size not a power of two.", 3682));
  if (ctx != NULL && ctx->ignoreResourceLimits) {
    int d = as_s3d_max_texture_size();
    if (w > d || h > d) as_tex_alloc_failed();
    return;
  }
  int m = as_tex_ceiling();
  if (w > m || h > m)
    as_throw(ArgumentError_new((char*)(m >= 4096
      ? "Error #3683: Texture too big (max is 4096x4096)."
      : "Error #3683: Texture too big (max is 2048x2048)."), 3683));
}
static void as_tex_check_cube(bool ignoreLimits, int size) {
  if (size <= 0)
    as_throw(ArgumentError_new((char*)"Error #3681: Texture size is zero.", 3681));
  if (!as_tex_is_pow2(size))
    as_throw(ArgumentError_new((char*)"Error #3682: Texture size not a power of two.", 3682));
  if (size > 1024) {
    if (ignoreLimits) as_tex_alloc_failed();
    else as_throw(ArgumentError_new((char*)"Error #3705: Cubemap texture too big (max is 1024x1024).", 3705));
  }
}
static void as_tex_check_rect(Context3D* ctx, int w, int h) {
  if (w <= 0 || h <= 0)
    as_throw(ArgumentError_new((char*)"Error #3681: Texture size is zero.", 3681));
  if (ctx != NULL && ctx->ignoreResourceLimits) {
    int d = as_s3d_max_texture_size();
    if (w > d || h > d) as_tex_alloc_failed();
    return;
  }
  int m = as_tex_ceiling();
  if (ctx->backBufferWidth > m) m = ctx->backBufferWidth;
  if (ctx->backBufferHeight > m) m = ctx->backBufferHeight;
  if (w > m || h > m)
    as_throw(ArgumentError_new((char*)(as_tex_ceiling() >= 4096
      ? "Error #3766: RectangleTexture too big (max is the larger of 4096x4096 or the size of the backbuffer)."
      : "Error #3766: RectangleTexture too big (max is the larger of 2048x2048 or the size of the backbuffer)."), 3766));
}
static Texture* Context3D_createTexture(void* _this, int width, int height, char* format, bool optimizeForRenderToTexture) {
  Context3D* ctx = (Context3D*)_this;
  as_tex_check_2d(ctx, width, height);
  Texture* t = Texture_new();
  t->width = width; t->height = height; t->format = format;
  if (optimizeForRenderToTexture) t->gpu = as_s3d_create_render_texture(ctx->gpu, width, height);
  t->ctx = ctx->gpu;
  return t;
}
