static void Context3D_drawToBitmapData(void* _this, BitmapData* destination) {
  Context3D* o = (Context3D*)_this;
  if (destination == NULL) return;
  if (o->gpu != NULL && destination->pixels != NULL) {
    uint8_t* rgba = (uint8_t*)malloc((size_t)o->backBufferWidth * o->backBufferHeight * 4);
    if (rgba != NULL) {
      if (as_s3d_readback_render(o->gpu, rgba)) {
        for (int y = 0; y < o->backBufferHeight; y++) {
          for (int x = 0; x < o->backBufferWidth; x++) {
            int idx = y * o->backBufferWidth + x;
            uint8_t b = rgba[idx * 4 + 0];
            uint8_t g = rgba[idx * 4 + 1];
            uint8_t r = rgba[idx * 4 + 2];
            uint8_t a = rgba[idx * 4 + 3];
            ((uint32_t*)destination->pixels)[idx] = ((uint32_t)a << 24) | ((uint32_t)r << 16) | ((uint32_t)g << 8) | (uint32_t)b;
          }
        }
      }
      free(rgba);
    }
  } else {
    memset(destination->pixels, 0, (size_t)destination->width * destination->height * 4);
  }
}
