  return !strcmp(p, "baseline") || !strcmp(p, "baselineExtended") || !strcmp(p, "baselineConstrained")
      || !strcmp(p, "enhanced") || !strcmp(p, "standard") || !strcmp(p, "standardConstrained")
      || !strcmp(p, "standardExtended");
