static void Stage_dispatchWheel(void* _this, double x, double y, double delta) {
  void* target = as_pick_hit(_this, x, y);
  if (target == NULL) return;
  DisplayObject* o = (DisplayObject*)target;
  if (as_is(target, &TextField_vt) && ((TextField*)target)->mouseWheelEnabled) {
    TextField* tf = (TextField*)target;
    int maxs = as_tf_line_count(tf) - as_tf_visible_lines(tf) + 1;
    if (maxs < 1) maxs = 1;
    int nv = tf->scrollV - (int)delta;
    if (nv < 1) nv = 1;
    if (nv > maxs) nv = maxs;
    tf->scrollV = nv;
  }
  MouseEvent* evt = MouseEvent_new((char*)"mouseWheel", true, false, x - o->x, y - o->y, NULL, false, false, false, false, delta);
  EventDispatcher_dispatchEvent(target, (Event*)evt);
}
static void Stage_dispatchFrame(void* _this) {
  (void)_this;
  int _fguard = 0;
  if (as_frame_guard == 0) { if (setjmp(as_frame_jmp) != 0) { as_frame_guard = 0; as_disp_depth = 0; return; } _fguard = 1; as_frame_guard = 1; }
  const double asc_frame_t0 = as_now_ms();
  gc_step();
  as_dbg_frame(as_now_ms() - asc_frame_t0);
  as_fre_pump();
  as_async_tick();
  as_timer_tick();
  as_mc_tick();
  as_audio_tick();
  static Event* evt = NULL;
  if (evt == NULL) { evt = Event_new((char*)"enterFrame", false, false); gc_root_register((void**)&evt); }
  for (int i = 0; i < as_ef_count; i++) {
    evt->target = NULL; evt->propStopped = false; evt->immStopped = false;
    EventDispatcher_dispatchEvent(as_ef_objs[i], evt);
  }
  if (_fguard) as_frame_guard = 0;
}
