// GC permanent user roots: window stages, ENTER_FRAME registry, and all
// pointer/boxed static fields and module variables. Called by gc_collect.
static void gc_mark_user_roots(void) {
  for (int i = 0; i < ASC_MAX_WINDOWS; i++) {
    gc_mark_ptr((void*)ASC_wins[i].stage);
    gc_mark_ptr(ASC_wins[i].window);
    gc_mark_ptr((void*)ASC_wins[i].title);
    gc_mark_ptr(ASC_wins[i].owner);
    gc_mark_ptr((void*)ASC_wins[i].system_chrome);
    gc_mark_ptr((void*)ASC_wins[i].type);
    gc_mark_ptr((void*)ASC_wins[i].render_mode);
    gc_mark_ptr((void*)ASC_wins[i].display_state);
  }
  gc_mark_ptr((void*)as_focus_obj);
  gc_mark_ptr((void*)as_tab_anchor);
  gc_mark_ptr((void*)ASC_native_app);
  gc_mark_ptr(ASC_drag_obj);
  gc_mark_ptr((void*)ASC_drag_bounds);
  gc_mark_ptr((void*)NetworkInfo__shell_singleton);
  gc_mark_ptr((void*)Clipboard__shell_singleton);
  gc_mark_ptr((void*)as_urld_user_agent);
  for (int i = 0; i < as_ef_count; i++) gc_mark_ptr(as_ef_objs[i]);
  gc_mark_ptr((void*)SoundMixer_audioPlaybackMode);
  gc_mark_ptr((void*)Mouse_cursor);
  gc_mark_ptr((void*)SharedObject__cache);
  gc_mark_ptr((void*)Vector3D_X_AXIS);
  gc_mark_ptr((void*)Vector3D_Y_AXIS);
  gc_mark_ptr((void*)Vector3D_Z_AXIS);
}

int main(void) {
  GC_NOTE_STACK_BASE();
  as_amf_wire();
  as_vec_fqn_wire();
  as_vec_wire();
  as_ba_wire();
  as_arrback_wire();
  char* _once0 = as_str_concat("name-collision: bind(1,2) = ", as_str_from_int(bind__(1, 2)));
  printf("%s\n", as_str_or_null(_once0));
  return as_exit_status;
}
